function href(file){ return file === "index.html" ? "/" : file.replace(/\.html$/g, ""); }
function pageUrl(file){ return site.url + "/" + (file === "index.html" ? "" : file.replace(/\.html$/g, "")); }
function esc(value){ return String(value).replace(/[&<>"]/g, function(char){ return {"&":"&amp;","<":"&lt;",">":"&gt;", '"':"&quot;"}[char]; }); }
function icon(name){ return '<span class="agency-icon" aria-hidden="true">' + name + '</span>'; }
function card(title, text, image, link, iconText){ return '<article class="service-card"><a href="' + href(link) + '"><figure><img src="' + image + '" alt="' + esc(title) + '"></figure><div class="service-body">' + icon(iconText) + '<h3>' + title + '</h3><p>' + text + '</p><span>En savoir plus</span></div></a></article>'; }
function contactFormHtml(){ return '<form id="contact-form" class="agency-form contact-form-pro" data-prepare-form data-form-kind="contact-agence"><label class="hp-field" aria-hidden="true">Site web<input name="site" tabindex="-1" autocomplete="off"></label><div class="contact-form-head"><p class="agency-kicker">Formulaire</p><h2>Décrivez-nous votre demande</h2><p>Quelques informations suffisent pour permettre à notre équipe de vous orienter vers le bon parcours.</p></div><div class="contact-form-steps"><fieldset><legend>1. Votre profil et votre demande</legend><div class="agency-form-grid"><label>Votre profil<select name="profil" required><option value="">Choisir</option><option>Propriétaire particulier</option><option>Propriétaire professionnel</option><option>Collectivité</option><option>Entreprise</option><option>Association</option><option>Porteur de projet</option><option>Habitant</option><option>Partenaire</option><option>Autre</option></select></label><label>Objet de la demande<select name="categorie" required><option value="">Choisir</option><option>Présenter un bien vacant</option><option>Signaler un bien ou un espace</option><option>Demander un accompagnement</option><option>Construire un partenariat territorial</option><option>Proposer des matériaux ou équipements</option><option>Proposer une expertise</option><option>Présenter un projet</option><option>Demander un rendez-vous</option><option>Demande presse ou communication</option><option>Autre demande</option></select></label></div></fieldset><fieldset><legend>2. Votre situation ou votre projet</legend><div class="agency-form-grid"><label>Adresse ou localisation<input name="localisation" type="text" placeholder="Adresse, commune ou secteur concerné"></label><label>Type de bien ou sujet<select name="type_bien"><option value="">Choisir si concerné</option><option>Logement</option><option>Commerce</option><option>Bâtiment</option><option>Friche</option><option>Terrain</option><option>Matériaux ou équipements</option><option>Projet territorial</option><option>Autre</option></select></label><label>Nature du projet<input name="objet" type="text" placeholder="Ex. bien vacant, partenariat, matériaux, rendez-vous"></label><label>Situation connue<input name="situation" type="text" placeholder="Vacant, à vérifier, projet à construire..."></label><label>Propriétaire connu<input name="proprietaire_connu" type="text" placeholder="Oui, non, vous-même, à confirmer"></label><label>Durée approximative<input name="duree_vacance" type="text" placeholder="Si connue"></label></div><label>Description de la demande<textarea id="contact-message" name="message" rows="6" placeholder="Expliquez le contexte, votre besoin, les informations disponibles et les suites souhaitées."></textarea></label><div class="contact-upload-note"><strong>Documents utiles</strong><p>Vous pouvez indiquer ici les pièces déjà disponibles : photographies, plans, diagnostics, courriers, documents de propriété, présentation du projet ou inventaire de matériaux. Les pièces complémentaires pourront être demandées ultérieurement.</p><textarea name="documents_disponibles" rows="3" placeholder="Documents disponibles ou à transmettre ensuite"></textarea></div></fieldset><fieldset><legend>3. Vos coordonnées et vos préférences</legend><div class="agency-form-grid"><label>Civilité<select name="civilite"><option value="">Choisir</option><option>Madame</option><option>Monsieur</option><option>Non précisé</option></select></label><label>Nom<input name="nom" type="text" autocomplete="family-name" required></label><label>Prénom<input name="prenom" type="text" autocomplete="given-name"></label><label>Organisation<input name="organisation" type="text" autocomplete="organization"></label><label>Fonction<input name="fonction" type="text"></label><label>Adresse e-mail<input name="email" type="email" autocomplete="email" required></label><label>Numéro de téléphone<input name="telephone" type="tel" autocomplete="tel"></label><label>Commune<input name="territoire" type="text"></label><label>Code postal<input name="code_postal" type="text" inputmode="numeric"></label><label>Préférence de contact<select name="preference_contact"><option>Réponse par e-mail</option><option>Être rappelé</option><option>Demander un rendez-vous</option><option>Échange en visioconférence</option></select></label><label>Disponibilités<select name="disponibilites"><option value="">Choisir</option><option>Matin</option><option>Après-midi</option><option>Créneau à préciser</option></select></label></div></fieldset></div><label class="agency-consent"><input name="consent" type="checkbox" value="true" data-summary-value="Oui" required> J\'accepte que mes informations soient utilisées pour traiter ma demande.</label><label class="agency-consent"><input name="exactitude" type="checkbox" value="true" data-summary-value="Oui" required> Je confirme l\'exactitude des informations transmises.</label><label class="agency-consent"><input name="actualites" type="checkbox" value="true" data-summary-value="Oui"> J\'accepte d\'être recontacté au sujet des actions et actualités de TVF.</label><div class="agency-actions contact-submit-actions"><button class="agency-btn" type="button" data-prepare-summary>Vérifier ma demande</button><button class="agency-btn agency-btn-alt" type="button" data-submit-form hidden>Envoyer ma demande</button><a class="agency-btn agency-btn-alt" href="mailto:' + contact.email + '" data-mailto-summary data-mailto-to="' + contact.email + '" data-mailto-subject="Demande Territoires Vivants France" hidden>Ouvrir l\'e-mail</a><button class="agency-btn agency-btn-ghost" type="button" data-copy-summary hidden>Copier le résumé</button><button class="agency-btn agency-btn-ghost" type="button" data-reset-form hidden>Effacer</button></div><p class="form-note" data-submit-status hidden role="status"></p><output class="form-summary" data-form-summary hidden aria-live="polite"></output><p class="contact-form-note">Vous recevrez un accusé de réception contenant une référence de demande lorsque l\'envoi est enregistré.</p></form>'; }
function formHtml(){ return '<form class="agency-form" data-prepare-form data-form-kind="demande-agence"><label class="hp-field" aria-hidden="true">Site web<input name="site" tabindex="-1" autocomplete="off"></label><div class="agency-form-grid"><label>Profil<select name="profil"><option value="">Choisir</option><option>Proprietaire</option><option>Collectivite</option><option>Entreprise</option><option>Partenaire</option><option>Association</option><option>Financeur</option><option>Citoyen</option></select></label><label>Type de demande<select name="categorie"><option value="">Choisir</option><option>Proposition de bien</option><option>Diagnostic territorial</option><option>Materiaux ou equipements</option><option>Partenariat</option><option>Financement / mecenat</option><option>Signalement</option><option>Rendez-vous</option></select></label><label>Nom / structure<input name="nom" type="text" autocomplete="name"></label><label>E-mail<input name="email" type="email" autocomplete="email"></label><label>Telephone<input name="telephone" type="tel" autocomplete="tel"></label><label>Commune / territoire<input name="territoire" type="text"></label><label>Objet<input name="objet" type="text"></label></div><label>Message<textarea name="message" rows="5" placeholder="Expliquez la demande, le bien, la ressource ou le besoin."></textarea></label><label class="agency-consent"><input name="consent" type="checkbox" value="true" data-summary-value="Oui"> J\'accepte que TVF utilise ces informations pour repondre a ma demande.</label><div class="agency-actions"><button class="agency-btn" type="button" data-prepare-summary>Preparer l\'envoi</button><button class="agency-btn agency-btn-alt" type="button" data-submit-form hidden>Envoyer a TVF</button><a class="agency-btn agency-btn-alt" href="mailto:' + contact.email + '" data-mailto-summary data-mailto-to="' + contact.email + '" data-mailto-subject="Demande Territoires Vivants France" hidden>Ouvrir l\'e-mail</a><button class="agency-btn agency-btn-ghost" type="button" data-copy-summary hidden>Copier le resume</button><button class="agency-btn agency-btn-ghost" type="button" data-reset-form hidden>Effacer</button></div><p class="form-note" data-submit-status hidden role="status"></p><output class="form-summary" data-form-summary hidden aria-live="polite"></output></form>'; }
