function footer(){ return '<footer class="agency-footer"><div class="agency-shell agency-footer-grid"><div><img src="assets/logo-territoires-vivants-france-web.png" alt="Territoires Vivants France"><p>Agence Territoriale de Revitalisation Immobiliere, un service porte par Territoires Vivants France.</p><p>Association loi 1901 a but non lucratif.</p></div><div><h2>Liens rapides</h2><a href="qui-sommes-nous">L\'agence</a><a href="proprietaires">Proprietaires</a><a href="collectivites">Collectivites</a><a href="entreprises">Entreprises</a><a href="contact">Contact</a></div><div><h2>Coordonnees</h2><a href="tel:' + contact.phoneHref + '">' + contact.phone + '</a><a href="mailto:' + contact.email + '">' + contact.email + '</a><p>' + contact.address + '</p></div><div><h2>Suivre TVF</h2><a href="' + socials.facebook + '">Facebook</a><a href="' + socials.instagram + '">Instagram</a><a href="' + socials.whatsapp + '">WhatsApp</a></div></div><div class="agency-shell agency-copy"><span>© 2026 Territoires Vivants France - Tous droits reserves.</span><span><a href="mentions-legales">Mentions legales</a> · <a href="politique-confidentialite">Confidentialite</a></span></div></footer>'; }
function home(){ return `<section class="agency-hero agency-hero-premium"><div class="agency-hero-text"><p class="agency-kicker">Agence territoriale</p><h1>Valorisons ensemble nos territoires, redonnons vie a l'immobilier vacant.</h1><p>Nous identifions, accompagnons et remettons en usage les logements, commerces, batiments, terrains et ressources inutilises au service des territoires.</p><div class="agency-actions"><a class="agency-btn" href="qui-sommes-nous">Decouvrir notre mission</a><a class="agency-btn agency-btn-alt" href="proprietaires">Declarer un bien vacant</a></div><div class="home-trust-row"><span>Association loi 1901</span><span>Saint-Etienne territoire pilote</span><span>Suivi par TVF OS</span></div></div><div class="agency-hero-media"><img src="${photos.hero}" alt="Centre-ville francais revitalise"><aside class="visitor-card"><p>Vous etes :</p><a href="proprietaires">Proprietaire <span>-></span></a><a href="collectivites">Collectivite <span>-></span></a><a href="entreprises">Entreprise / partenaire <span>-></span></a><a href="benevoles-citoyens">Citoyen <span>-></span></a></aside></div></section><section class="home-proof"><div class="agency-shell home-proof-grid"><article><p class="agency-kicker">Cadre</p><h2>Une entree unique pour qualifier les situations.</h2><p>Chaque demande est rattachee a un profil, un motif, une categorie et une suite possible.</p></article><article><strong>1</strong><span>Demande recue</span></article><article><strong>2</strong><span>Situation qualifiee</span></article><article><strong>3</strong><span>Dossier suivi</span></article><article><strong>4</strong><span>Orientation ou action</span></article></div></section><section class="impact-band"><div class="agency-shell"><div><p>Notre impact</p><h2>Au service des territoires</h2></div><article>${icon('H')}<strong>A suivre</strong><span>Biens identifies et qualifies</span></article><article>${icon('C')}<strong>A suivre</strong><span>Cooperations engagees</span></article><article>${icon('M')}<strong>A suivre</strong><span>Ressources valorisees</span></article><a class="agency-btn agency-btn-outline" href="impact">Voir les resultats</a></div></section><section class="agency-section home-services"><div class="agency-shell section-title"><p class="agency-kicker">Nos actions</p><h2>Des solutions concretes pour revitaliser durablement les territoires</h2><a href="nos-actions">Decouvrir toutes nos actions -></a></div><div class="agency-shell services-grid">${card('Habitat vivant','Identifier, etudier et remettre en usage des logements vacants ou inutilises.',photos.habitat,'proprietaires.html','H')}${card('Commerce vivant','Accompagner la reactivation de locaux commerciaux et d activites utiles.',photos.commerce,'nos-actions.html','C')}${card('Friches et terrains vivants','Qualifier des espaces delaisses et imaginer de nouveaux usages territoriaux.',photos.friches,'nos-actions.html','F')}${card('Materiautheque solidaire','Valoriser les materiaux et ressources dormantes dans des projets encadres.',photos.materiaux,'entreprises.html','M')}${card('Solidarite et insertion','Mobiliser les competences, l engagement et les chantiers encadres.',photos.solidarite,'benevoles-citoyens.html','S')}</div></section><section class="mission-block"><div class="agency-shell mission-grid"><div><p class="agency-kicker">Notre mission</p><h2>Une agence engagée pour un immobilier utile.</h2><p>TVF n'est pas une agence immobiliere classique. Sa mission est de transformer une situation dormante en dossier lisible : comprendre le bien, verifier le besoin, reunir les acteurs, preparer le cadre et suivre les suites dans TVF OS.</p><p>Le modele associe les proprietaires, collectivites, entreprises, associations, citoyens et partenaires autour d'un objectif commun : remettre en usage ce qui peut redevenir utile.</p><a class="agency-btn" href="qui-sommes-nous">Comprendre TVF</a></div><img src="assets/photos/home-mission-immobilier-utile.jpeg" alt="Propriétaire et chargé de mission devant un immeuble à étudier"></div></section><section class="agency-section commitments"><div class="agency-shell"><p class="agency-kicker">Engagements</p><div class="commit-grid"><article>${icon('1')}<h3>Approche territoriale</h3><p>Chaque dossier part d'un bien, d'un besoin local et d'un cadre realiste.</p></article><article>${icon('2')}<h3>Solutions adaptees</h3><p>Diagnostic, orientation, convention, materiaux ou cooperation selon la situation.</p></article><article>${icon('3')}<h3>Transparence</h3><p>Pas de faux chiffres ni de partenaires non officialises.</p></article><article>${icon('4')}<h3>Suivi professionnel</h3><p>Les demandes sont rattachees a TVF OS pour conserver l'historique.</p></article></div></div></section>`; }
function agencyAbout(){ return `<section class="about-hero"><div class="agency-shell about-hero-grid"><div class="about-hero-card"><p class="agency-kicker">L'agence</p><h1>L'Agence Territoriale de Revitalisation Immobilière</h1><p>Territoires Vivants France agit pour repérer, comprendre et remettre en usage les logements, commerces, bâtiments, friches et terrains vacants.</p><p>Portée par une association loi 1901, l'Agence associe propriétaires, collectivités, entreprises, associations et habitants afin de construire des solutions adaptées à chaque bien et à chaque territoire.</p><div class="agency-actions"><a class="agency-btn" href="nos-actions">Découvrir notre mission</a><a class="agency-btn agency-btn-alt" href="contact">Prendre rendez-vous</a></div></div><figure><img src="${photos.hero}" alt="Centre-ville français en transformation"></figure></div></section>
<section class="about-split"><div class="agency-shell about-split-grid"><div><p class="agency-kicker">Qui sommes-nous ?</p><h2>Une agence au service des territoires vivants</h2><p>Territoires Vivants France développe une mission d'intérêt général autour de la vacance immobilière, de la revitalisation des centres-villes, de la valorisation du patrimoine bâti et de la remise en usage des espaces délaissés.</p><p>Notre rôle ne consiste pas uniquement à identifier des biens vacants. Nous cherchons à comprendre leur situation, à mobiliser les bons interlocuteurs et à définir les conditions nécessaires à leur remise en usage.</p></div><img src="${photos.ville}" alt="Panorama urbain de Saint-Étienne"></div></section>
<section class="about-split about-split-alt"><div class="agency-shell about-split-grid"><img src="${photos.habitat}" alt="Immeuble rénové"><div><p class="agency-kicker">Notre raison d'être</p><h2>Redonner une utilité aux biens vacants</h2><p>Un logement fermé, un commerce inoccupé, une friche ou un terrain délaissé peuvent devenir une difficulté pour un propriétaire et pour un territoire.</p><ul><li>Dégradation du bâtiment et perte de valeur patrimoniale.</li><li>Charges sans usage et contraintes administratives.</li><li>Affaiblissement d'une rue, d'un quartier ou d'un centre-ville.</li><li>Consommation inutile de nouveaux espaces.</li></ul></div></div></section>
<section class="about-quote"><div class="agency-shell"><blockquote>Chaque bien vacant représente une opportunité de redonner vie à un territoire.</blockquote><p>TVF favorise la réutilisation du patrimoine existant et accompagne la création de projets adaptés aux besoins locaux.</p></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Notre mission</p><h2>Observer, accompagner et remettre en usage</h2></div><div class="agency-shell values-grid"><article>${icon('1')}<h3>Repérer</h3><p>Identifier les logements, commerces, bâtiments, terrains et friches susceptibles de faire l'objet d'un projet.</p></article><article>${icon('2')}<h3>Comprendre</h3><p>Étudier la situation du bien, son environnement, ses contraintes, son état apparent et les besoins du territoire.</p></article><article>${icon('3')}<h3>Accompagner</h3><p>Écouter le propriétaire ou le porteur de projet et l'aider à identifier les solutions envisageables.</p></article><article>${icon('4')}<h3>Mobiliser</h3><p>Mettre en relation les acteurs utiles : collectivités, professionnels, associations, entreprises et partenaires techniques.</p></article><article>${icon('5')}<h3>Suivre</h3><p>Structurer les étapes du projet et suivre son évolution jusqu'à sa remise en usage lorsque les conditions le permettent.</p></article></div></section>
<section class="about-method"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Notre méthode</p><h2>Une démarche construite autour de chaque bien</h2></div><ol class="about-timeline"><li><strong>Signalement ou repérage</strong><span>Le bien est signalé ou repéré dans le cadre d'une observation territoriale.</span></li><li><strong>Ouverture du dossier</strong><span>Adresse, nature du bien, état apparent, situation connue et coordonnées sont enregistrés.</span></li><li><strong>Analyse préliminaire</strong><span>TVF comprend la situation et détermine les recherches nécessaires.</span></li><li><strong>Prise de contact</strong><span>Lorsque le propriétaire est identifié, un échange est proposé.</span></li><li><strong>Visite et diagnostic</strong><span>Une visite peut préciser l'état, les contraintes et le potentiel de valorisation.</span></li><li><strong>Scénario de remise en usage</strong><span>Rénovation, occupation temporaire, projet associatif, commerce, réemploi ou transformation.</span></li><li><strong>Mobilisation des partenaires</strong><span>TVF oriente ou met en relation avec les acteurs compétents.</span></li><li><strong>Suivi du projet</strong><span>Le dossier est suivi dans les étapes administratives, techniques et partenariales.</span></li></ol></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Domaines d'intervention</p><h2>Une action globale sur la vacance et la revitalisation</h2></div><div class="agency-shell services-grid about-domains">${card('Habitat Vivant','Repérer et accompagner la remise en usage des logements vacants ou dégradés.',photos.habitat,'proprietaires.html','H')}${card('Commerce Vivant','Contribuer à la revitalisation des locaux commerciaux et des centralités.',photos.commerce,'nos-actions.html','C')}${card('Friches et Terrains Vivants','Étudier les possibilités de transformation des friches, bâtiments délaissés et terrains inutilisés.',photos.friches,'nos-actions.html','F')}${card('Matériauthèque Solidaire','Favoriser le réemploi des matériaux dans des projets utiles, écologiques et solidaires.',photos.materiaux,'entreprises.html','M')}${card('Solidarité et Insertion','Soutenir des projets contribuant a l inclusion, a l apprentissage et au cadre de vie.',photos.solidarite,'benevoles-citoyens.html','S')}</div></section>
<section class="audience-section"><div class="agency-shell"><p class="agency-kicker">À qui s'adresse l'Agence ?</p><div class="audience-grid"><article><h3>Propriétaires</h3><p>Étudier les possibilités de valorisation d'un logement, commerce, bâtiment ou terrain vacant.</p></article><article><h3>Collectivités</h3><p>Mieux comprendre la vacance, identifier des biens et engager une démarche de revitalisation.</p></article><article><h3>Entreprises</h3><p>Contribuer par expertise, partenariat ou matériaux réemployables.</p></article><article><h3>Associations</h3><p>Rechercher un espace, un accompagnement ou des partenaires.</p></article><article><h3>Habitants</h3><p>Signaler un bien vacant ou participer à l'amélioration du quartier.</p></article></div></div></section>
<section class="about-split"><div class="agency-shell about-split-grid"><div><p class="agency-kicker">Territoire pilote</p><h2>Saint-Étienne, premier territoire de déploiement</h2><p>Territoires Vivants France développe son premier dispositif opérationnel à Saint-Étienne. Ce territoire pilote doit permettre de structurer progressivement le repérage des biens vacants, la prise de contact avec les propriétaires, la constitution des dossiers, les partenariats locaux et les outils de suivi de TVF.</p><p>Les enseignements issus de ce territoire pourront ensuite servir au déploiement de l'approche TVF dans d'autres territoires.</p><a class="agency-btn" href="saint-etienne">Voir le territoire pilote</a></div><img src="${photos.hero}" alt="Saint-Étienne territoire pilote"></div></section>
<section class="agency-section"><div class="agency-shell commitments"><p class="agency-kicker">Nos engagements</p><h2>Une action responsable, transparente et territoriale</h2><div class="commit-grid"><article>${icon('✓')}<h3>Respecter les propriétaires</h3><p>Le propriétaire conserve ses droits et ses décisions.</p></article><article>${icon('✓')}<h3>Ne pas promettre l'impossible</h3><p>Aucune aide, financement ou rénovation n'est présenté comme automatique.</p></article><article>${icon('✓')}<h3>Protéger les informations</h3><p>Les informations transmises sont traitées dans un cadre de dossier.</p></article><article>${icon('✓')}<h3>Agir avec les bons professionnels</h3><p>Les opérations réglementées sont orientées vers les acteurs habilités.</p></article></div></div></section>
<section class="about-split about-split-alt"><div class="agency-shell about-split-grid"><img src="${photos.friches}" alt="Friche et quartier à requalifier"><div><p class="agency-kicker">Une approche différente</p><h2>Plus qu'un bien, nous regardons son environnement</h2><p>TVF ne considère pas un bien vacant de manière isolée. Nous étudions aussi son implantation, les besoins locaux, l'activité économique, l'accessibilité, les partenariats possibles et l'impact potentiel de sa remise en activité.</p><p>Cette approche territoriale permet de rechercher une solution cohérente pour le propriétaire, le bien et son environnement.</p></div></div></section>
<section class="final-cta"><div class="agency-shell"><p class="agency-kicker">Construisons ensemble</p><h2>De nouvelles possibilités pour les biens vacants.</h2><p>Vous êtes propriétaire, collectivité, entreprise, association ou habitant ? TVF peut étudier votre demande et vous orienter vers le parcours adapté.</p><div class="agency-actions"><a class="agency-btn" href="contact">Prendre rendez-vous</a><a class="agency-btn agency-btn-alt" href="proprietaires">Déclarer un bien</a><a class="agency-btn agency-btn-outline" href="contact">Nous contacter</a></div></div></section>`; }

function ownersPage(){ return `<section class="owner-hero"><div class="agency-shell owner-hero-grid"><div class="owner-hero-card"><p class="agency-kicker">Propriétaires</p><h1>Vous possédez un bien vacant ? Donnons-lui une nouvelle perspective.</h1><p>Logement, local commercial, bâtiment ou terrain : chaque bien possède une histoire, un potentiel et des enjeux qui lui sont propres.</p><p>L'Agence Territoriale de Revitalisation Immobilière accompagne les propriétaires qui souhaitent comprendre la situation de leur bien, étudier les possibilités de valorisation et construire un projet adapté à leurs objectifs.</p><div class="agency-actions"><a class="agency-btn" href="contact">Déclarer mon bien</a><a class="agency-btn agency-btn-alt" href="contact">Demander un rendez-vous</a></div></div><figure><img src="${photos.habitat}" alt="Immeuble rénové et remis en valeur"></figure></div></section>
<section class="owner-intro"><div class="agency-shell owner-intro-grid"><div><p class="agency-kicker">Pourquoi faire appel à l'Agence ?</p><h2>Pourquoi nous confier votre projet ?</h2><p>Un bien vacant peut rapidement entraîner des coûts, une dégradation du patrimoine ou une perte d'attractivité pour son environnement.</p></div><p>Notre rôle est de vous accompagner dans l'analyse de votre situation et de vous aider à identifier les solutions les plus adaptées à votre projet, en mobilisant les partenaires compétents lorsque cela est nécessaire.</p></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Biens concernés</p><h2>Nous accompagnons tous types de biens</h2></div><div class="agency-shell owner-property-grid"><article><img src="${photos.habitat}" alt="Logement vacant à valoriser"><div>${icon('L')}<h3>Logements vacants</h3><p>Maisons, appartements, immeubles et copropriétés pouvant faire l'objet d'une étude de remise en usage.</p><a href="contact">Découvrir</a></div></article><article><img src="${photos.commerce}" alt="Local commercial vacant"><div>${icon('C')}<h3>Commerces</h3><p>Locaux commerciaux, boutiques, rez-de-chaussée actifs et cellules vacantes en centre-ville ou quartier.</p><a href="contact">Découvrir</a></div></article><article><img src="${photos.ville}" alt="Bâtiment à étudier"><div>${icon('B')}<h3>Bâtiments</h3><p>Bureaux, ateliers, bâtiments d'activité ou bâtiments inutilisés nécessitant une orientation claire.</p><a href="contact">Découvrir</a></div></article><article><img src="${photos.friches}" alt="Terrain ou friche urbaine"><div>${icon('T')}<h3>Terrains et friches</h3><p>Terrains constructibles, friches urbaines et anciens sites d'activité à qualifier avant toute décision.</p><a href="contact">Découvrir</a></div></article></div></section>
<section class="owner-challenges"><div class="agency-shell owner-split"><figure><img src="${photos.friches}" alt="Bien vacant nécessitant une étude"></figure><div><p class="agency-kicker">Difficultés fréquentes</p><h2>Vous êtes concerné si...</h2><ul><li>Votre bien est inoccupé depuis plusieurs mois ou années.</li><li>Les charges deviennent importantes sans usage réel.</li><li>Des travaux sont à prévoir avant toute remise en usage.</li><li>La situation résulte d'une succession ou d'une indivision complexe.</li><li>Vous manquez de temps pour identifier les bonnes solutions.</li><li>Vous souhaitez être accompagné sans perdre la maîtrise de vos décisions.</li></ul><a class="agency-btn" href="contact">Échanger avec un chargé de mission</a></div></div></section>
<section class="owner-process"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Notre accompagnement</p><h2>Un parcours clair, étape par étape</h2></div><ol class="owner-steps"><li><strong>Échange</strong><span>Nous prenons connaissance de votre demande et des caractéristiques de votre bien.</span></li><li><strong>Analyse</strong><span>Nous réalisons une première étude afin d'identifier les enjeux du projet.</span></li><li><strong>Visite</strong><span>Lorsque cela est nécessaire, un chargé de mission peut organiser une visite du bien.</span></li><li><strong>Étude des solutions</strong><span>Nous identifions les possibilités de remise en usage, de valorisation ou de réhabilitation.</span></li><li><strong>Partenaires</strong><span>Nous vous orientons vers les acteurs compétents en fonction de votre projet.</span></li><li><strong>Suivi</strong><span>Nous restons à vos côtés tout au long de l'avancement du dossier.</span></li></ol></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Solutions étudiées</p><h2>Chaque bien est unique</h2></div><div class="agency-shell owner-solutions"><article><img src="${photos.habitat}" alt="Réhabilitation d'un bien"><h3>Réhabilitation</h3><p>Étudier les conditions d'une remise en état, dans un cadre adapté au bien et aux choix du propriétaire.</p><a href="contact">En savoir plus</a></article><article><img src="${photos.commerce}" alt="Remise en activité commerciale"><h3>Remise en activité</h3><p>Identifier un nouvel usage possible pour un local commercial, un rez-de-chaussée ou un bâtiment vacant.</p><a href="contact">En savoir plus</a></article><article><img src="${photos.solidarite}" alt="Occupation temporaire encadrée"><h3>Occupation temporaire</h3><p>Explorer, lorsque le contexte le permet, une utilisation temporaire encadrée par une convention adaptée.</p><a href="contact">En savoir plus</a></article><article><img src="${photos.friches}" alt="Valorisation foncière"><h3>Valorisation foncière</h3><p>Comprendre le potentiel d'un terrain, d'une friche ou d'un site vacant avant de décider de la suite.</p><a href="contact">En savoir plus</a></article></div><div class="agency-shell owner-note"><p>Les solutions proposées dépendent toujours des caractéristiques du bien, des choix du propriétaire et du cadre réglementaire applicable.</p></div></section>
<section class="owner-aid"><div class="agency-shell owner-aid-grid"><div><p class="agency-kicker">Aides et dispositifs</p><h2>Des dispositifs peuvent être mobilisés selon votre situation.</h2><p>Certaines opérations peuvent, selon leur nature et les critères d'éligibilité, bénéficier de dispositifs d'accompagnement ou d'aides publiques. L'Agence vous informe sur les dispositifs existants et vous oriente vers les organismes compétents lorsque cela est pertinent.</p></div><ul><li>MaPrimeRénov'</li><li>Éco-PTZ</li><li>Certificats d'économies d'énergie</li><li>Aides de l'Anah, si éligibilité confirmée</li><li>Dispositifs locaux selon le territoire</li></ul></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Engagements</p><h2>Un accompagnement clair et respectueux</h2></div><div class="agency-shell commit-grid owner-commitments"><article>${icon('1')}<h3>Écoute</h3><p>Comprendre votre situation avant de proposer une orientation.</p></article><article>${icon('2')}<h3>Transparence</h3><p>Présenter clairement les limites, les étapes et les suites possibles.</p></article><article>${icon('3')}<h3>Suivi</h3><p>Conserver une trace claire de l'avancement de votre dossier.</p></article><article>${icon('4')}<h3>Respect</h3><p>Vos décisions de propriétaire restent au centre du parcours.</p></article><article>${icon('5')}<h3>Partenariat</h3><p>Mobiliser les bons interlocuteurs lorsque le dossier le justifie.</p></article><article>${icon('6')}<h3>Prudence</h3><p>Aucune aide, rénovation ou acceptation n'est présentée comme automatique.</p></article></div></section>

<section class="owner-legal-frame"><div class="agency-shell info-grid"><article><p class="agency-kicker">Cadre immobilier</p><h2>Ce que TVF peut faire aujourd'hui.</h2><p>TVF peut recueillir une demande, analyser les informations transmises, orienter le propri&eacute;taire, proposer un cadre de convention, rechercher des partenaires et suivre le dossier.</p><p>Les activit&eacute;s r&eacute;glement&eacute;es, notamment transaction, gestion locative, mandat, perception de fonds, diagnostics obligatoires ou travaux soumis &agrave; qualification, rel&egrave;vent des professionnels habilit&eacute;s lorsque le cadre l'exige.</p></article><article><p class="agency-kicker">Conditions</p><h2>Aucune intervention automatique.</h2><p>La gratuit&eacute;, le co&ucirc;t, la mission, les responsabilit&eacute;s et les suites possibles sont pr&eacute;cis&eacute;s avant toute intervention. Une demande peut &ecirc;tre compl&eacute;t&eacute;e, orient&eacute;e ou class&eacute;e sans suite.</p><a class="agency-btn" href="documents">Voir les pi&egrave;ces utiles</a></article></div></section>
<section class="owner-faq"><div class="agency-shell owner-faq-grid"><div><p class="agency-kicker">Questions fréquentes</p><h2>Avant de déposer votre demande</h2></div><div class="owner-accordion"><details><summary>Qui peut déposer un dossier ?</summary><p>Tout propriétaire ou représentant habilité d'un bien concerné peut transmettre une demande.</p></details><details><summary>L'accompagnement est-il obligatoire jusqu'au bout ?</summary><p>Non. Vous restez libre de poursuivre ou non votre projet à chaque étape.</p></details><details><summary>Puis-je rester propriétaire de mon bien ?</summary><p>Oui. L'étude de votre dossier ne modifie pas vos droits de propriété.</p></details><details><summary>Quels documents seront demandés ?</summary><p>Les pièces dépendent de la nature du bien, de votre qualité à agir et du projet envisagé.</p></details></div></div></section>
<section class="owner-declare"><div class="agency-shell"><div class="owner-declare-card"><p class="agency-kicker">Déclarer un bien</p><h2>Vous souhaitez étudier les possibilités de valorisation de votre bien ?</h2><p>Déposez votre demande en ligne ou prenez rendez-vous avec un chargé de mission.</p><div class="agency-actions"><a class="agency-btn" href="contact">Déclarer mon bien</a><a class="agency-btn agency-btn-alt" href="contact">Être rappelé</a></div></div></div></section>
<section class="final-cta"><div class="agency-shell"><p class="agency-kicker">Contact propriétaire</p><h2>Un chargé de mission vous répond.</h2><p>Vous pouvez appeler, envoyer un message ou transmettre votre demande depuis le formulaire de contact.</p><div class="agency-actions"><a class="agency-btn" href="tel:${contact.phoneHref}">Appeler ${contact.phone}</a><a class="agency-btn agency-btn-alt" href="mailto:${contact.email}">Envoyer un message</a></div></div></section>`; }

function collectivitiesPage(){ return `<section class="collectivity-hero"><div class="agency-shell collectivity-hero-grid"><div class="collectivity-hero-card"><p class="agency-kicker">Collectivités</p><h1>Agir durablement contre la vacance et redonner vie aux territoires.</h1><p>Logements inoccupés, commerces fermés, bâtiments dégradés, friches ou terrains sans usage : la vacance immobilière peut fragiliser l'attractivité d'une commune, dégrader le cadre de vie et ralentir le développement local.</p><p>L'Agence Territoriale de Revitalisation Immobilière accompagne les collectivités dans le repérage des situations de vacance, la compréhension des enjeux locaux et la construction de démarches adaptées à leur territoire.</p><div class="agency-actions"><a class="agency-btn" href="contact">Présenter mon territoire</a><a class="agency-btn agency-btn-alt" href="contact">Demander un rendez-vous</a></div></div><figure><img src="${photos.hero}" alt="Centre-ville français et espace public revitalisé"></figure></div></section>
<section class="collectivity-intro"><div class="agency-shell collectivity-intro-grid"><div><p class="agency-kicker">Réponse territoriale</p><h2>Une réponse territoriale à la vacance immobilière</h2><p>Chaque territoire possède ses propres réalités. TVF propose une approche transversale qui ne se limite pas au traitement d'un bien isolé.</p></div><div class="collectivity-list-card"><p>La vacance peut concerner :</p><ul><li>logements anciens ou dégradés ;</li><li>immeubles durablement inoccupés ;</li><li>commerces fermés ;</li><li>bâtiments publics ou privés sans usage ;</li><li>friches urbaines ou économiques ;</li><li>terrains délaissés ;</li><li>secteurs touchés par une perte d'attractivité.</li></ul></div></div></section>
<section class="collectivity-why"><div class="agency-shell collectivity-split"><figure><img src="${photos.ville}" alt="Territoire urbain à observer"></figure><div><p class="agency-kicker">Pourquoi faire appel à TVF ?</p><h2>Organiser, qualifier et suivre les situations dans le temps.</h2><p>Une collectivité peut disposer de nombreuses informations sans toujours avoir les moyens humains ou opérationnels pour les organiser, contacter les propriétaires et suivre chaque situation.</p><ul><li>Structurer un repérage territorial.</li><li>Organiser les signalements et centraliser les informations utiles.</li><li>Qualifier les biens identifiés et prioriser les suites.</li><li>Faciliter le dialogue avec les propriétaires.</li><li>Identifier des pistes de remise en usage et mobiliser des partenaires.</li><li>Assurer un suivi opérationnel des dossiers.</li></ul><p>L'intervention est définie avec la collectivité en fonction de ses priorités, de ses compétences et des moyens disponibles.</p></div></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Domaines d'intervention</p><h2>Des leviers adaptés aux réalités locales</h2></div><div class="agency-shell collectivity-domain-grid"><article>${icon('H')}<h3>Vacance résidentielle</h3><p>Repérage et analyse des logements, maisons, appartements ou immeubles durablement inoccupés afin de mieux comprendre les causes de la vacance.</p></article><article>${icon('C')}<h3>Revitalisation commerciale</h3><p>Observation des cellules fermées, des rues fragilisées et des usages possibles pour soutenir les centralités et l'installation d'activités.</p></article><article>${icon('F')}<h3>Friches et bâtiments délaissés</h3><p>Première qualification de friches urbaines, bâtiments inutilisés, anciens sites d'activité ou ensembles immobiliers complexes.</p></article><article>${icon('T')}<h3>Foncier et terrains sans usage</h3><p>Observation des terrains délaissés ou insuffisamment valorisés afin d'étudier les usages pouvant répondre aux besoins locaux.</p></article><article>${icon('M')}<h3>Réemploi des matériaux</h3><p>Identification de possibilités de récupération et de réemploi de matériaux issus de chantiers, stocks inutilisés ou opérations de transformation.</p></article><article>${icon('S')}<h3>Solidarité et insertion</h3><p>Recherche de projets immobiliers pouvant accueillir des activités associatives, sociales, éducatives, solidaires ou liées à l'insertion.</p></article></div></section>
<section class="collectivity-process"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Notre accompagnement</p><h2>Une mission structurée avec la collectivité</h2></div><ol class="collectivity-steps"><li><strong>Échange territorial</strong><span>Comprendre les priorités, les secteurs concernés et les dispositifs déjà engagés.</span></li><li><strong>Définition du périmètre</strong><span>Territoire, catégories de biens, objectifs, acteurs à associer et modalités de suivi.</span></li><li><strong>Recueil des informations</strong><span>Services, terrain, signalements, données accessibles, partenaires et acteurs locaux.</span></li><li><strong>Qualification</strong><span>Fiche par bien : localisation, nature, état apparent, environnement, priorité et démarches.</span></li><li><strong>Relations propriétaires</strong><span>Préparer ou faciliter la prise de contact lorsque le cadre de mission le permet.</span></li><li><strong>Recherche de solutions</strong><span>Remise en état, nouvel usage, occupation temporaire, projet commercial ou associatif.</span></li><li><strong>Partenaires</strong><span>Mettre en relation les acteurs compétents selon leurs rôles respectifs.</span></li><li><strong>Suivi et restitution</strong><span>Restitution adaptée au périmètre convenu et suivi structuré des situations étudiées.</span></li></ol></div></section>
<section class="collectivity-observatory"><div class="agency-shell collectivity-observatory-grid"><div><p class="agency-kicker">Observatoire territorial</p><h2>Mieux connaître pour mieux agir</h2><p>TVF développe une méthode d'observation permettant de regrouper et d'organiser les informations liées aux biens vacants ou délaissés, dans le respect des règles applicables à la protection des données, au droit de propriété et à l'accès aux données administratives.</p></div><div class="collectivity-toolbox"><article>Cartographie des biens repérés</article><article>Fiches par bien</article><article>Classification par type de vacance</article><article>Niveau de priorité</article><article>Historique des démarches</article><article>Statut du dossier</article><article>Solutions envisagées</article><article>Partenaires mobilisés</article></div></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Outils</p><h2>Des outils adaptés aux besoins des collectivités</h2></div><div class="agency-shell collectivity-tools-grid"><article>Cartographie opérationnelle</article><article>Registre interne des biens repérés</article><article>Tableau de suivi</article><article>Fiches de terrain</article><article>Formulaire de signalement</article><article>Espace documentaire</article><article>Synthèses territoriales</article><article>Comptes rendus de suivi</article><article>Espace de collaboration dans TVF OS</article></div><div class="agency-shell collectivity-note"><p>Les accès, les données visibles et les modalités de partage sont définis avec la collectivité.</p></div></section>
<section class="collectivity-complement"><div class="agency-shell collectivity-split"><div><p class="agency-kicker">Intervention complémentaire</p><h2>Un outil de repérage, coordination et suivi territorial.</h2><p>TVF n'a pas vocation à remplacer les services de la collectivité, les établissements publics, les opérateurs fonciers ou les professionnels habilités.</p><p>L'Agence intervient comme un outil complémentaire de repérage, coordination, médiation, accompagnement, orientation et suivi territorial.</p><p>Les missions nécessitant une expertise réglementée, une autorisation particulière ou une compétence publique sont réalisées par les organismes et professionnels compétents.</p></div><figure><img src="${photos.friches}" alt="Friche urbaine à qualifier"></figure></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Coopération locale</p><h2>Une démarche construite avec les acteurs locaux</h2></div><div class="agency-shell collectivity-actor-grid"><article>Services communaux ou intercommunaux</article><article>Élus</article><article>Établissements publics fonciers</article><article>Services de l'État</article><article>Chambres consulaires</article><article>Bailleurs</article><article>Professionnels de l'immobilier</article><article>Associations</article><article>Commerçants</article><article>Entreprises</article><article>Habitants</article></div></section>
<section class="collectivity-benefits"><div class="agency-shell"><p class="agency-kicker">Bénéfices pour le territoire</p><h2>Ce qu'une démarche structurée peut apporter</h2><div class="collectivity-benefit-grid"><article>Améliorer la connaissance de la vacance.</article><article>Prévenir la dégradation des bâtiments.</article><article>Renforcer le dialogue avec les propriétaires.</article><article>Soutenir la remise en usage du patrimoine existant.</article><article>Préserver les centres-villes et les quartiers.</article><article>Favoriser l'installation d'activités.</article><article>Limiter l'artificialisation de nouveaux sols.</article><article>Soutenir l'économie locale.</article><article>Améliorer le cadre de vie.</article><article>Développer des projets solidaires et durables.</article></div><p>Ces résultats dépendent de la situation des biens, de l'engagement des propriétaires, des compétences mobilisées et des moyens disponibles.</p></div></section>
<section class="collectivity-conventions"><div class="agency-shell collectivity-conventions-grid"><div><p class="agency-kicker">Modalités de coopération</p><h2>Un cadre écrit pour chaque mission.</h2><p>L'intervention de TVF peut être formalisée selon la nature du projet au moyen d'une convention de partenariat, d'expérimentation, d'une mission territoriale définie, d'un programme d'actions, d'un partenariat autour du signalement ou d'un projet commun de revitalisation.</p></div><div><h3>La convention précise notamment :</h3><ul><li>objectifs et territoire concerné ;</li><li>missions de chaque partie ;</li><li>données mobilisées ;</li><li>modalités de suivi ;</li><li>durée et moyens affectés ;</li><li>conditions financières lorsqu'elles existent.</li></ul></div></div></section>
<section class="about-split"><div class="agency-shell about-split-grid"><div><p class="agency-kicker">Territoire pilote</p><h2>Saint-Étienne, premier cadre opérationnel.</h2><p>Territoires Vivants France développe son premier cadre opérationnel à Saint-Étienne afin de tester et améliorer progressivement les méthodes de repérage, les fiches de qualification, le suivi des propriétaires, l'organisation des partenariats, l'utilisation de TVF OS, les outils de restitution et les parcours de remise en usage.</p><p>Aucun partenariat institutionnel n'est présenté comme acquis tant qu'il n'a pas été officiellement formalisé.</p><a class="agency-btn" href="saint-etienne">Voir le territoire pilote</a></div><img src="${photos.hero}" alt="Saint-Étienne territoire pilote"></div></section>
<section class="owner-faq collectivity-faq"><div class="agency-shell owner-faq-grid"><div><p class="agency-kicker">Questions fréquentes</p><h2>Avant d'engager une mission</h2></div><div class="owner-accordion"><details><summary>TVF peut-elle accéder directement aux fichiers fiscaux sur les logements vacants ?</summary><p>Non. Certaines données sont réservées aux administrations et aux collectivités habilitées. Leur transmission et leur utilisation doivent respecter le cadre légal applicable.</p></details><details><summary>La collectivité peut-elle partager ses propres données avec TVF ?</summary><p>Cela dépend de la nature des informations, de leur finalité et du cadre juridique retenu. Les modalités doivent être précisées avant toute transmission.</p></details><details><summary>TVF peut-elle contacter les propriétaires ?</summary><p>Cela peut être prévu dans le cadre d'une mission définie avec la collectivité, en respectant le droit applicable et les droits des personnes concernées.</p></details><details><summary>TVF réalise-t-elle les diagnostics techniques réglementaires ?</summary><p>Non. Les diagnostics réglementaires doivent être réalisés par des professionnels certifiés.</p></details><details><summary>TVF peut-elle garantir la remise en usage d'un bien ?</summary><p>Non. La réussite dépend notamment de l'accord du propriétaire, de l'état du bien, de la réglementation, du financement et de la mobilisation des partenaires.</p></details><details><summary>L'accompagnement est-il payant ?</summary><p>Les conditions dépendent de la nature et de l'étendue de la mission. Elles sont précisées dans la convention ou la proposition d'intervention.</p></details></div></div></section>
<section class="final-cta"><div class="agency-shell"><p class="agency-kicker">Contact collectivités</p><h2>Construisons une démarche adaptée à votre territoire.</h2><p>Votre commune ou votre intercommunalité souhaite mieux connaître la vacance, organiser le repérage de biens délaissés ou développer une expérimentation territoriale ?</p><div class="agency-actions"><a class="agency-btn" href="contact">Présenter mon territoire</a><a class="agency-btn agency-btn-alt" href="contact">Demander un rendez-vous</a><a class="agency-btn agency-btn-outline" href="mailto:${contact.email}">Contacter l'Agence</a></div></div></section>`; }
function enterprisesPage(){ return `<section class="business-hero"><div class="agency-shell business-hero-grid"><div class="business-hero-card"><p class="agency-kicker">Entreprises et partenaires</p><h1>Votre entreprise peut contribuer à redonner vie aux territoires.</h1><p>Matériaux inutilisés, équipements disponibles, compétences techniques, mécénat, prestations ou partenariats : les entreprises disposent de nombreuses ressources pouvant participer à la revitalisation des logements, commerces, bâtiments et espaces délaissés.</p><p>Territoires Vivants France construit avec les acteurs économiques des coopérations concrètes, adaptées à leur activité, à leurs moyens et aux besoins des territoires.</p><div class="agency-actions"><a class="agency-btn" href="contact">Devenir partenaire</a><a class="agency-btn agency-btn-alt" href="contact">Proposer une contribution</a></div><p class="business-hero-note">Chaque partenariat fait l'objet d'un échange préalable et d'un cadre adapté.</p></div><figure><img src="${photos.solidarite}" alt="Entreprise et chantier de rénovation encadré"></figure></div></section>
<section class="business-intro"><div class="agency-shell"><div class="business-intro-copy"><p class="agency-kicker">Engagement économique</p><h2>Mobiliser les forces économiques au service du territoire</h2><p>Les entreprises jouent un rôle essentiel dans la transformation des territoires. Elles possèdent des savoir-faire, des ressources, des réseaux et des capacités d'intervention utiles à la remise en usage du patrimoine existant.</p><p>L'Agence Territoriale de Revitalisation Immobilière facilite la rencontre entre les besoins identifiés sur le terrain et les entreprises souhaitant s'engager dans une démarche territoriale, environnementale ou solidaire.</p><p>Notre objectif est de construire des partenariats utiles, réalistes et clairement définis, sans créer d'engagement automatique pour l'entreprise.</p></div><div class="business-markers"><span>Ressources</span><span>Compétences</span><span>Impact territorial</span></div></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Contribuer</p><h2>Comment votre entreprise peut agir</h2></div><div class="agency-shell business-action-grid"><article>${icon('M')}<h3>Donner des matériaux</h3><p>Matériaux neufs, surplus, fins de série, stocks inutilisés ou ressources pouvant être réemployées peuvent être étudiés pour des projets identifiés ou la Matériauthèque Solidaire.</p><a href="contact">Proposer des matériaux</a></article><article>${icon('E')}<h3>Mettre à disposition des équipements</h3><p>Mobilier, outillage, équipements techniques, éléments d'aménagement ou fournitures peuvent parfois retrouver une utilité dans un projet territorial.</p><a href="contact">Proposer un équipement</a></article><article>${icon('X')}<h3>Apporter une expertise</h3><p>Architectes, artisans, bureaux d'études, professionnels du bâtiment, du foncier, du numérique, de la logistique ou de l'environnement peuvent contribuer par leur savoir-faire.</p><a href="contact">Mettre une expertise à disposition</a></article><article>${icon('A')}<h3>Participer à une action</h3><p>Une entreprise peut mobiliser ses équipes dans le cadre d'une action collective, d'un chantier participatif encadré, d'une opération de réemploi ou d'une journée d'engagement.</p><a href="contact">Participer à une action</a></article><article>${icon('F')}<h3>Soutenir financièrement un projet</h3><p>Un soutien financier peut concerner TVF ou une action clairement identifiée. Objectifs, affectation, modalités de suivi et cadre sont précisés avant engagement.</p><a href="contact">Soutenir un projet</a></article><article>${icon('P')}<h3>Construire un partenariat territorial</h3><p>Votre entreprise souhaite accompagner un quartier, soutenir une opération de revitalisation ou intégrer une démarche de responsabilité territoriale ?</p><a href="contact">Construire un partenariat</a></article></div></section>
<section class="business-resources"><div class="agency-shell business-split"><figure><img src="${photos.materiaux}" alt="Matériaux rangés et prêts au réemploi"></figure><div><p class="agency-kicker">Ressources recherchées</p><h2>Des ressources utiles à la remise en usage des biens</h2><p>Territoires Vivants France peut rechercher, selon les projets en cours, différents types de ressources.</p><div class="business-resource-cols"><div><h3>Bâtiment et rénovation</h3><p>Peinture, revêtements, carrelage, bois, portes, fenêtres, sanitaires, éléments électriques, quincaillerie, isolants et finitions.</p></div><div><h3>Aménagement et équipement</h3><p>Mobilier, rayonnages, luminaires, équipements de bureau, rangement, informatique et outillage professionnel.</p></div><div><h3>Services et compétences</h3><p>Diagnostics, études, conseil, architecture, travaux, transport, stockage, communication, numérique et insertion.</p></div></div><p>Toute proposition est étudiée avant acceptation. TVF peut refuser une ressource qui ne correspond pas aux besoins, qui présente un risque ou dont les conditions de transport, de stockage ou de réemploi ne sont pas adaptées.</p><a class="agency-btn" href="contact">Signaler une ressource disponible</a></div></div></section>
<section class="business-materials"><div class="agency-shell business-materials-grid"><div><p class="agency-kicker">Matériauthèque Solidaire</p><h2>Organiser la collecte, le référencement et l'affectation des ressources.</h2><p>La Matériauthèque Solidaire a vocation à organiser la collecte, le référencement et la mobilisation de matériaux ou d'équipements pouvant être réemployés dans des projets suivis par Territoires Vivants France.</p><p>Elle ne constitue pas un espace de distribution libre au public. Les ressources collectées sont destinées en priorité aux opérations identifiées, aux partenariats conventionnés et aux projets territoriaux répondant aux objectifs de TVF.</p><div class="agency-actions"><a class="agency-btn agency-btn-alt" href="contact">Proposer un stock</a><a class="agency-btn agency-btn-outline" href="nos-actions">Découvrir la Matériauthèque</a></div></div><figure><img src="${photos.materiaux}" alt="Matériaux de réemploi organisés"></figure></div><div class="agency-shell business-flow"><span>Collecter</span><span>Vérifier</span><span>Référencer</span><span>Affecter à un projet</span></div></section>
<section class="business-benefits"><div class="agency-shell business-benefits-grid"><div><p class="agency-kicker">Pourquoi devenir partenaire ?</p><h2>Un engagement concret, visible et utile</h2></div><div class="business-benefit-cards"><article><h3>Renforcer votre ancrage territorial</h3><p>Participer à des actions directement liées aux besoins des communes, des quartiers et de leurs habitants.</p></article><article><h3>Valoriser vos ressources inutilisées</h3><p>Étudier le réemploi de matériaux, équipements ou stocks qui pourraient autrement être immobilisés ou éliminés.</p></article><article><h3>Mobiliser vos collaborateurs</h3><p>Associer vos équipes à une démarche concrète favorisant coopération, transmission des compétences et engagement collectif.</p></article><article><h3>Contribuer à l'économie circulaire</h3><p>Favoriser la réutilisation du patrimoine bâti et des ressources existantes plutôt que la consommation systématique de nouveaux matériaux.</p></article><article><h3>Soutenir l'activité locale</h3><p>Participer à des projets susceptibles de mobiliser entreprises, artisans, associations et professionnels du territoire.</p></article><article><h3>Donner du sens à votre engagement</h3><p>Relier votre politique sociale, environnementale ou territoriale à des actions suivies et clairement identifiées.</p></article></div></div></section>
<section class="business-frame"><div class="agency-shell business-frame-grid"><div><p class="agency-kicker">Coopération encadrée</p><h2>Des partenariats définis avec transparence</h2><p>Avant toute intervention, TVF échange avec l'entreprise afin de préciser la nature de la contribution, les ressources ou compétences mobilisées, le territoire ou le projet concerné, les responsabilités, les conditions de transport, de stockage ou d'intervention, les règles de communication, la durée du partenariat et les modalités de suivi.</p><p>Selon la nature de la coopération, le partenariat peut être formalisé par une convention de partenariat, une convention de don, une convention de mise à disposition, un accord de mécénat lorsque les conditions sont réunies, une commande, une prestation ou un programme d'actions partagé.</p><p>Aucun partenariat n'est considéré comme acquis avant sa validation et sa formalisation par les parties concernées.</p></div><div class="business-dossier"><span>Proposition</span><span>Analyse</span><span>Cadre</span><span>Convention</span><span>Suivi</span></div></div></section>
<section class="business-tax"><div class="agency-shell business-tax-card"><div>${icon('i')}</div><div><h2>Dons, mécénat et fiscalité</h2><p>Selon la nature de l'opération, la situation de l'association et les conditions prévues par la réglementation, certains soutiens peuvent relever du mécénat d'entreprise.</p><p>L'éligibilité à une réduction fiscale et la délivrance d'un reçu fiscal ne doivent jamais être considérées comme automatiques. Elles dépendent du cadre juridique applicable et de la nature réelle de la contribution. L'entreprise reste responsable de l'appréciation fiscale de sa situation et peut se rapprocher de son conseil habituel.</p><a href="contact">Échanger sur les modalités du partenariat</a></div></div></section>
<section class="business-process"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Parcours partenaire</p><h2>De la première proposition au bilan de l'action</h2></div><ol class="business-steps"><li><strong>Prise de contact</strong><span>L'entreprise présente ses ressources, son projet ou son souhait d'engagement.</span></li><li><strong>Étude</strong><span>TVF vérifie la cohérence avec ses missions et les besoins existants.</span></li><li><strong>Définition</strong><span>Objectifs, responsabilités, moyens et conditions d'intervention sont précisés.</span></li><li><strong>Formalisation</strong><span>Une convention, un accord ou un document adapté est signé si nécessaire.</span></li><li><strong>Mise en œuvre</strong><span>La contribution est mobilisée dans le respect du cadre défini.</span></li><li><strong>Suivi</strong><span>TVF conserve les informations utiles au suivi de l'action ou de la ressource.</span></li><li><strong>Restitution</strong><span>Un retour peut être transmis selon la nature et l'importance du partenariat.</span></li></ol></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Profils d'entreprises</p><h2>Toutes les entreprises peuvent contribuer</h2></div><div class="agency-shell business-profile-grid"><article><h3>Artisans et entreprises du bâtiment</h3><p>Travaux, rénovation, matériaux, diagnostics, conseils techniques et transmission de savoir-faire.</p></article><article><h3>Commerces et distributeurs</h3><p>Fins de série, mobilier, équipements, stocks non utilisés et soutien aux centralités commerciales.</p></article><article><h3>Promoteurs et acteurs immobiliers</h3><p>Expertise immobilière, foncière, technique ou territoriale et participation à des projets de transformation.</p></article><article><h3>Entreprises industrielles</h3><p>Matériaux, logistique, équipements, réemploi, mécénat de compétences ou économie circulaire.</p></article><article><h3>Entreprises de services</h3><p>Conseil, communication, informatique, juridique, comptabilité, formation et accompagnement opérationnel.</p></article><article><h3>Grandes entreprises et fondations</h3><p>Soutien à des programmes territoriaux, mécénat, appels à projets et mobilisation de collaborateurs.</p></article></div></section>
<section class="business-commit"><div class="agency-shell"><p class="agency-kicker">Engagements TVF</p><h2>Nos engagements envers les entreprises partenaires</h2><div class="business-commit-grid"><article>Étudier chaque proposition avec attention.</article><article>Présenter clairement l'utilisation envisagée des ressources.</article><article>Ne pas accepter de contribution inutile ou inadaptée.</article><article>Préciser les responsabilités de chaque intervenant.</article><article>Formaliser les partenariats lorsque cela est nécessaire.</article><article>Protéger les informations confidentielles transmises.</article><article>Communiquer fidèlement sur les actions réalisées.</article><article>Ne pas utiliser le nom ou le logo d'une entreprise sans accord.</article><article>Assurer un suivi proportionné à la contribution.</article><article>Respecter la réglementation applicable.</article></div></div></section>
<section class="business-launch"><div class="agency-shell business-launch-card"><p class="agency-kicker">Lancement</p><h2>Les premières coopérations territoriales se construisent</h2><p>Territoires Vivants France développe actuellement son réseau d'entreprises, d'artisans et de partenaires techniques autour de son territoire pilote.</p><p>Les projets, contributions acceptées et résultats obtenus seront présentés dans cette rubrique après leur mise en œuvre et leur validation.</p><a class="agency-btn" href="contact">Devenir l'un des premiers partenaires</a></div></section>
<section class="owner-faq business-faq"><div class="agency-shell owner-faq-grid"><div><p class="agency-kicker">Questions fréquentes</p><h2>Avant de proposer une contribution</h2></div><div class="owner-accordion"><details><summary>Quels types de matériaux pouvons-nous proposer ?</summary><p>Tout matériau ou équipement susceptible d'être utile à un projet peut être présenté. Son acceptation dépend de son état, de sa conformité, de son utilité et des possibilités de transport ou de stockage.</p></details><details><summary>TVF accepte-t-elle tous les dons ?</summary><p>Non. Chaque proposition est étudiée avant acceptation. TVF peut refuser une contribution inadaptée, dangereuse, trop dégradée ou ne répondant à aucun besoin identifié.</p></details><details><summary>Qui organise le transport ?</summary><p>Cela dépend du partenariat. Les responsabilités et les coûts de transport sont définis avant l'acceptation de la contribution.</p></details><details><summary>Notre entreprise peut-elle intervenir sur un chantier ?</summary><p>Oui, lorsqu'un projet le permet et que les compétences, assurances, autorisations et règles de sécurité nécessaires sont réunies.</p></details><details><summary>Pouvons-nous choisir le projet soutenu ?</summary><p>Une affectation précise peut être envisagée lorsqu'elle est compatible avec les besoins de TVF et les conditions du partenariat.</p></details><details><summary>Notre logo sera-t-il affiché ?</summary><p>L'utilisation du nom, du logo et des éléments de communication de l'entreprise est définie avec son accord préalable.</p></details><details><summary>Recevrons-nous un justificatif de notre contribution ?</summary><p>Les documents remis dépendent de la nature juridique de l'opération. Une convention, une attestation de remise ou un autre document de suivi peut être établi lorsque cela est approprié.</p></details><details><summary>Une contribution ouvre-t-elle automatiquement droit à une réduction fiscale ?</summary><p>Non. L'éligibilité dépend de la réglementation, de la situation de TVF et de la nature de la contribution.</p></details></div></div></section>
<section class="business-final"><div class="agency-shell business-final-card"><p class="agency-kicker">Partenariat</p><h2>Construisons un partenariat utile à votre territoire</h2><p>Votre entreprise dispose de matériaux, d'équipements, de compétences ou souhaite soutenir une action de revitalisation ? Présentez-nous votre proposition.</p><div class="agency-actions"><a class="agency-btn" href="contact">Proposer des matériaux</a><a class="agency-btn agency-btn-alt" href="contact">Mettre une expertise à disposition</a><a class="agency-btn agency-btn-ghost" href="contact">Devenir partenaire</a></div></div></section>
<section class="agency-section"><div class="agency-shell narrow"><p class="agency-kicker">Coordonnées entreprises</p><h2>Pôle entreprises et partenariats</h2><p><strong>Territoires Vivants France</strong><br>Agence Territoriale de Revitalisation Immobilière<br>${contact.address}<br>Téléphone : <a href="tel:${contact.phoneHref}">${contact.phone}</a><br>E-mail : <a href="mailto:${contact.email}">${contact.email}</a><br>Site : <a href="${site.url}">www.territoiresvivantsfrance.fr</a></p></div></section>`; }
function actionsPage(){ return `<section class="actions-hero"><div class="agency-shell actions-hero-grid"><div class="actions-hero-card"><p class="agency-kicker">Nos actions</p><h1>Transformer la vacance en nouvelles possibilités pour les territoires.</h1><p>Territoires Vivants France agit sur les logements vacants, les commerces fermés, les bâtiments délaissés, les friches, les terrains sans usage et les ressources pouvant être réemployées.</p><p>À travers son Agence Territoriale de Revitalisation Immobilière, TVF organise des actions de repérage, d'analyse, d'accompagnement, de mise en relation et de suivi afin de favoriser la remise en usage du patrimoine existant.</p><div class="agency-actions"><a class="agency-btn" href="#domaines-action">Découvrir nos domaines d'action</a><a class="agency-btn agency-btn-alt" href="contact">Signaler un bien ou un espace</a></div><p class="actions-hero-note">Chaque action est construite selon la situation du bien, les choix du propriétaire et les besoins du territoire.</p></div><div class="actions-mosaic" aria-label="Réalités territoriales accompagnées"><img src="${photos.habitat}" alt="Logement vacant ou réhabilité"><img src="${photos.commerce}" alt="Commerce de centre-ville"><img src="${photos.friches}" alt="Friche ou espace délaissé"><img src="${photos.materiaux}" alt="Matériaux de réemploi"><img src="${photos.hero}" alt="Centre-ville vivant"></div></div></section>
<section class="actions-intro"><div class="agency-shell"><div class="actions-intro-copy"><p class="agency-kicker">Méthode territoriale</p><h2>Une approche globale de la revitalisation immobilière</h2><p>Un bien vacant ne constitue pas uniquement une adresse inoccupée. Sa situation peut être liée à des travaux importants, une succession, une difficulté administrative, une absence de projet, une transformation du quartier ou un manque de moyens.</p><p>TVF développe une méthode territoriale permettant de prendre en compte la situation du bien, les intentions du propriétaire, son environnement, les besoins du territoire, les usages envisageables, les acteurs pouvant intervenir et les conditions nécessaires à sa remise en usage.</p><p>Nos actions sont organisées autour de cinq pôles complémentaires.</p></div><div class="actions-method-line"><span>Repérer</span><span>Comprendre</span><span>Accompagner</span><span>Mobiliser</span><span>Suivre</span></div></div></section>
<section id="domaines-action" class="action-pole action-pole-light"><div class="agency-shell action-pole-grid"><figure><img src="${photos.habitat}" alt="Rue résidentielle et immeuble ancien"></figure><div><p class="agency-kicker">Pôle 01 — Habitat</p><h2>Habitat Vivant</h2><h3>Remettre les logements vacants au cœur de la vie locale</h3><p>Le pôle Habitat Vivant agit autour des maisons, appartements, immeubles et logements durablement inoccupés. L'objectif est de mieux comprendre les causes de leur vacance, d'établir un dialogue avec les propriétaires et d'étudier les conditions permettant une remise en usage adaptée.</p><div class="action-detail-grid"><article><h4>Repérage des logements vacants</h4><p>Le repérage peut être alimenté par les propriétaires, collectivités, signalements d'habitants, partenaires, observations de terrain et informations légalement accessibles.</p></article><article><h4>Qualification de la situation</h4><p>TVF rassemble les informations disponibles : nature du logement, état apparent, durée d'inoccupation connue, environnement et difficultés identifiées.</p></article><article><h4>Dialogue avec les propriétaires</h4><p>Lorsque cela est possible, TVF échange avec le propriétaire pour connaître sa situation, ses intentions et les solutions qu'il souhaite étudier.</p></article><article><h4>Étude de remise en usage</h4><p>Rénovation, location, vente, occupation temporaire encadrée, projet solidaire, opérateur compétent ou orientation vers les dispositifs existants.</p></article></div><p class="action-audience"><strong>Pour qui ?</strong> Propriétaires particuliers, indivisions, copropriétés, collectivités, associations et porteurs de projets.</p><div class="agency-actions"><a class="agency-btn" href="contact">Présenter un logement</a><a class="agency-btn agency-btn-alt" href="proprietaires">Découvrir le parcours propriétaire</a></div></div></div></section>
<section class="action-pole action-pole-beige action-pole-reverse"><div class="agency-shell action-pole-grid"><div><p class="agency-kicker">Pôle 02 — Commerce</p><h2>Commerce Vivant</h2><h3>Redonner une activité aux locaux et aux centralités fragilisées</h3><p>Le pôle Commerce Vivant intervient autour des boutiques, cellules commerciales, locaux professionnels et rez-de-chaussée durablement fermés. La vacance commerciale peut affaiblir une rue, réduire l'attractivité d'un quartier et accélérer la dégradation des immeubles.</p><div class="action-detail-grid"><article><h4>Repérage des locaux vacants</h4><p>Observation des cellules commerciales fermées, rues fragilisées et secteurs nécessitant une attention particulière.</p></article><article><h4>Création de fiches de locaux</h4><p>Adresse, type de local, surface connue, état apparent, environnement commercial, accessibilité, usages envisageables et état d'avancement.</p></article><article><h4>Prise de contact</h4><p>TVF peut faciliter le dialogue avec le propriétaire pour comprendre sa situation et son souhait de nouvel usage.</p></article><article><h4>Mise en relation</h4><p>Propriétaires, porteurs de projets, commerçants, artisans, associations, entreprises, collectivités et professionnels compétents.</p></article></div><p class="action-audience"><strong>Usages possibles :</strong> commerce, atelier, bureau, espace associatif, activité culturelle, usage temporaire ou expérimentation territoriale.</p><div class="agency-actions"><a class="agency-btn" href="contact">Signaler un local vacant</a><a class="agency-btn agency-btn-alt" href="contact">Proposer une activité</a></div></div><figure><img src="${photos.commerce}" alt="Rue commerçante ou local commercial"></figure></div></section>
<section class="action-pole action-pole-light"><div class="agency-shell action-pole-grid"><figure><img src="${photos.friches}" alt="Friche urbaine et terrain délaissé"></figure><div><p class="agency-kicker">Pôle 03 — Foncier et friches</p><h2>Friches et Terrains Vivants</h2><h3>Révéler le potentiel des espaces délaissés</h3><p>Ce pôle agit autour des anciens sites d'activité, bâtiments sans usage, terrains délaissés et espaces insuffisamment valorisés. Ces biens peuvent nécessiter une approche foncière, technique, environnementale, réglementaire et territoriale.</p><div class="action-detail-grid"><article><h4>Identification</h4><p>Repérage des espaces susceptibles de faire l'objet d'une étude ou d'un projet de transformation.</p></article><article><h4>Première qualification</h4><p>Localisation, superficie connue, ancien usage, état apparent, accessibilité, environnement, contraintes connues et besoins du secteur.</p></article><article><h4>Acteurs concernés</h4><p>Propriétaire, collectivité, établissement public foncier, urbaniste, architecte, bureau d'études, géomètre ou services compétents.</p></article><article><h4>Usages possibles</h4><p>Logement, activité économique, artisanat, services, agriculture urbaine, équipement local, association, espace temporaire ou renaturation.</p></article></div><p class="action-audience">TVF facilite l'organisation du projet et l'orientation vers les professionnels compétents, sans se substituer aux études réglementaires nécessaires.</p><div class="agency-actions"><a class="agency-btn" href="contact">Signaler une friche</a><a class="agency-btn agency-btn-alt" href="contact">Présenter un terrain</a></div></div></div></section>
<section class="action-pole action-pole-dark action-pole-reverse"><div class="agency-shell action-pole-grid"><div><p class="agency-kicker">Pôle 04 — Réemploi</p><h2>Matériauthèque Solidaire</h2><h3>Donner une seconde utilité aux matériaux et aux équipements</h3><p>La Matériauthèque Solidaire de TVF a vocation à collecter, référencer et mobiliser des matériaux, équipements et ressources pouvant être réemployés dans des projets suivis par l'Agence.</p><div class="action-detail-grid"><article><h4>Identifier les ressources</h4><p>Entreprises, artisans, distributeurs, gestionnaires de stocks, acteurs immobiliers, collectivités et structures disposant de matériaux inutilisés.</p></article><article><h4>Étudier les propositions</h4><p>État, utilité, sécurité, conformité requise, transport, stockage et besoins des projets suivis.</p></article><article><h4>Référencer</h4><p>Nature, quantité, état, emplacement, disponibilité et affectation éventuelle des ressources acceptées.</p></article><article><h4>Affecter à un projet</h4><p>Ressources mobilisées prioritairement pour projets suivis par TVF, conventions, actions territoriales et projets solidaires.</p></article></div><p class="action-audience">Les ressources ne sont pas distribuées librement au public. TVF peut refuser toute ressource inadaptée, dangereuse ou sans besoin identifié.</p><div class="agency-actions"><a class="agency-btn agency-btn-alt" href="contact">Proposer des matériaux</a><a class="agency-btn agency-btn-outline" href="entreprises">Découvrir la Matériauthèque</a></div></div><figure><img src="${photos.materiaux}" alt="Espace de stockage de matériaux réemployables"></figure></div><div class="agency-shell actions-flow"><span>Collecter</span><span>Vérifier</span><span>Référencer</span><span>Stocker</span><span>Affecter</span></div></section>
<section class="action-pole action-pole-soft action-pole-reverse"><div class="agency-shell action-pole-grid"><div><p class="agency-kicker">Pôle 05 — Utilité sociale</p><h2>Solidarité et Insertion</h2><h3>Faire de la revitalisation un levier d'utilité sociale</h3><p>La remise en usage du patrimoine existant peut contribuer à l'apprentissage, à l'insertion, à la coopération locale et au développement d'activités utiles. TVF recherche des liens entre projets immobiliers, besoins sociaux et acteurs capables de proposer un accompagnement adapté.</p><div class="action-detail-grid"><article><h4>Projets à dimension sociale</h4><p>Activités associatives, ateliers, formation, insertion, services de proximité, culture, intergénérationnel et initiatives solidaires.</p></article><article><h4>Mobilisation des partenaires</h4><p>Associations, structures d'insertion, organismes de formation, entreprises, artisans, collectivités, fondations et acteurs de l'ESS.</p></article><article><h4>Transmission de compétences</h4><p>Ateliers pratiques, sensibilisation, découverte des métiers, transmission de savoir-faire et chantiers encadrés.</p></article><article><h4>Soutien aux initiatives locales</h4><p>Accompagnement de la structuration lorsque l'initiative répond à un besoin local et aux missions de l'Agence.</p></article></div><p class="action-audience">TVF ne se substitue pas aux organismes d'insertion, employeurs, centres de formation ou professionnels habilités.</p><div class="agency-actions"><a class="agency-btn" href="contact">Présenter un projet solidaire</a><a class="agency-btn agency-btn-alt" href="entreprises">Devenir partenaire</a></div></div><figure><img src="${photos.solidarite}" alt="Équipe en atelier et action locale"></figure></div></section>
<section class="actions-coordination"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Action coordonnée</p><h2>Des pôles complémentaires autour d'un même projet</h2></div><div class="actions-coordination-grid"><div class="coordination-schema"><span>Bien ou espace repéré</span><span>Analyse territoriale</span><span>Mobilisation des pôles</span><span>Construction du projet</span><span>Suivi de la remise en usage</span></div><div><p>Un même bien peut relever de plusieurs domaines d'intervention. Un immeuble vacant peut comprendre des logements dans les étages, un local commercial au rez-de-chaussée, des matériaux pouvant être réemployés et un espace susceptible d'accueillir une activité associative.</p><p>TVF organise les informations et les interlocuteurs autour d'une vision globale du projet.</p><div class="actions-pole-tags"><span>Habitat</span><span>Commerce</span><span>Friches</span><span>Réemploi</span><span>Solidarité</span></div></div></div></div></section>
<section class="actions-process"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Déclenchement d'une action</p><h2>De l'identification du bien au suivi du projet</h2></div><ol class="actions-steps"><li><strong>Repérage ou signalement</strong><span>Un bien, un local, une friche ou une ressource est signalé à TVF.</span></li><li><strong>Enregistrement</strong><span>Les premières informations sont enregistrées et un dossier peut être ouvert.</span></li><li><strong>Analyse préliminaire</strong><span>TVF examine la situation connue, les besoins et les recherches nécessaires.</span></li><li><strong>Prise de contact</strong><span>Les acteurs concernés sont contactés lorsque cela est possible et pertinent.</span></li><li><strong>Orientations</strong><span>Les premières possibilités d'intervention ou de remise en usage sont étudiées.</span></li><li><strong>Partenaires</strong><span>Les professionnels et organismes compétents sont sollicités selon les besoins.</span></li><li><strong>Suivi</strong><span>Le dossier est suivi dans TVF OS ou les outils internes jusqu'à clôture ou mise en œuvre.</span></li></ol></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Modes d'intervention</p><h2>Comment TVF peut intervenir</h2></div><div class="agency-shell actions-mode-grid"><article>${icon('O')}<h3>Observation territoriale</h3><p>Repérer et organiser les informations relatives aux logements, locaux, bâtiments, friches et terrains vacants.</p></article><article>${icon('P')}<h3>Accompagnement des propriétaires</h3><p>Comprendre la situation du bien et étudier les possibilités compatibles avec les objectifs du propriétaire.</p></article><article>${icon('C')}<h3>Appui aux collectivités</h3><p>Participer à la structuration d'une démarche de repérage, qualification et suivi de la vacance.</p></article><article>${icon('M')}<h3>Mise en relation</h3><p>Faciliter les échanges entre propriétaires, collectivités, entreprises, associations et professionnels compétents.</p></article><article>${icon('G')}<h3>Coordination de projet</h3><p>Organiser les informations, les étapes et les intervenants autour d'un projet territorial.</p></article><article>${icon('R')}<h3>Réemploi et ressources</h3><p>Identifier les matériaux, équipements, compétences et soutiens pouvant contribuer aux projets suivis.</p></article></div></section>
<section class="actions-territory"><div class="agency-shell actions-territory-grid"><div class="france-card"><span>France</span><strong>Saint-Étienne</strong><p>Territoire pilote</p></div><div><p class="agency-kicker">Où agissons-nous ?</p><h2>Un premier déploiement à Saint-Étienne</h2><p>Territoires Vivants France développe son premier cadre opérationnel à Saint-Étienne. Ce territoire pilote doit permettre de structurer et d'améliorer progressivement les méthodes de repérage, la constitution des dossiers, le suivi des biens, les relations avec les propriétaires, l'organisation des partenariats, la mobilisation des entreprises, l'utilisation de TVF OS et les outils d'observation territoriale.</p><p>L'ambition est de construire une méthode pouvant ensuite être adaptée à d'autres territoires, selon les partenariats et les moyens mobilisés.</p><a class="agency-btn" href="saint-etienne">Découvrir le territoire pilote</a></div></div></section>
<section class="actions-launch"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Actions en cours</p><h2>Les premières actions se structurent</h2></div><p class="actions-launch-intro">Territoires Vivants France construit actuellement les outils, partenariats et méthodes nécessaires au déploiement de son Agence Territoriale de Revitalisation Immobilière.</p><div class="actions-launch-grid"><article><span>En développement</span><h3>Structuration de l'Observatoire</h3><p>Création d'une méthode de repérage, de qualification et de suivi des biens vacants ou délaissés.</p><a href="observatoire">Voir l'Observatoire</a></article><article><span>En préparation</span><h3>Déploiement du territoire pilote</h3><p>Organisation des premiers parcours opérationnels à Saint-Étienne.</p><a href="saint-etienne">Voir Saint-Étienne</a></article><article><span>En structuration</span><h3>Développement de la Matériauthèque</h3><p>Recherche de partenariats pour la collecte, le stockage et l'affectation de matériaux réemployables.</p><a href="entreprises">Voir entreprises</a></article></div><p class="actions-launch-foot">Les projets engagés, partenariats formalisés et résultats obtenus seront présentés après leur validation.</p></div></section>
<section class="actions-indicators"><div class="agency-shell actions-indicators-grid"><div><p class="agency-kicker">Indicateurs</p><h2>Mesurer l'évolution de nos actions</h2><p>TVF souhaite suivre progressivement les résultats de son intervention à partir d'indicateurs vérifiables. Les données seront publiées lorsqu'elles seront suffisamment consolidées et vérifiées.</p><a class="agency-btn agency-btn-outline" href="observatoire">Découvrir l'Observatoire</a></div><div class="indicator-placeholders"><article><strong>À publier</strong><span>Biens signalés</span></article><article><strong>À publier</strong><span>Dossiers étudiés</span></article><article><strong>À publier</strong><span>Partenariats formalisés</span></article><article><strong>À publier</strong><span>Ressources réemployées</span></article></div></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Participer</p><h2>Chacun peut contribuer à la revitalisation des territoires</h2></div><div class="agency-shell actions-participate-grid"><article><img src="${photos.habitat}" alt="Propriétaire et bien vacant"><h3>Vous êtes propriétaire</h3><p>Présentez un logement, un commerce, un bâtiment, une friche ou un terrain vacant.</p><a class="agency-btn" href="proprietaires">Déclarer mon bien</a></article><article><img src="${photos.ville}" alt="Collectivité et territoire"><h3>Vous représentez une collectivité</h3><p>Construisez avec TVF une démarche de repérage, d'observation ou de revitalisation.</p><a class="agency-btn" href="collectivites">Présenter mon territoire</a></article><article><img src="${photos.materiaux}" alt="Entreprise et matériaux"><h3>Vous êtes une entreprise</h3><p>Proposez des matériaux, des équipements, une expertise ou un partenariat.</p><a class="agency-btn" href="entreprises">Devenir partenaire</a></article><article><img src="${photos.solidarite}" alt="Habitants et association"><h3>Vous êtes habitant ou association</h3><p>Signalez une situation, présentez un besoin local ou proposez un projet utile.</p><a class="agency-btn" href="contact">Nous contacter</a></article></div></section>
<section class="owner-faq actions-faq"><div class="agency-shell owner-faq-grid"><div><p class="agency-kicker">Questions fréquentes</p><h2>Comprendre le cadre des actions</h2></div><div class="owner-accordion"><details><summary>TVF réalise-t-elle directement les travaux ?</summary><p>Pas systématiquement. Les travaux nécessitant une qualification, une assurance ou une compétence particulière doivent être réalisés par les entreprises et professionnels compétents.</p></details><details><summary>TVF peut-elle obliger un propriétaire à agir ?</summary><p>Non. TVF intervient dans le respect du droit de propriété. Les pouvoirs de police, procédures administratives et mesures coercitives relèvent des autorités compétentes.</p></details><details><summary>Un habitant peut-il signaler un bien vacant ?</summary><p>Oui. Un signalement peut être transmis à TVF. Il ne permet toutefois pas d'affirmer juridiquement qu'un bien est vacant, abandonné ou sans propriétaire.</p></details><details><summary>TVF peut-elle retrouver le propriétaire d'un bien ?</summary><p>TVF peut organiser des recherches à partir des informations légalement accessibles ou dans le cadre d'un partenariat. Certaines données restent réservées aux administrations et organismes habilités.</p></details><details><summary>Tous les biens signalés font-ils l'objet d'un projet ?</summary><p>Non. La suite dépend des informations disponibles, de la situation du bien, de l'accord du propriétaire, des priorités territoriales et des moyens mobilisables.</p></details><details><summary>TVF achète-t-elle les biens vacants ?</summary><p>L'Agence n'a pas vocation à acheter automatiquement les biens signalés. Elle étudie les orientations possibles et mobilise les acteurs adaptés au projet.</p></details><details><summary>Les actions de TVF sont-elles gratuites ?</summary><p>Les conditions dépendent de la nature du service, du bénéficiaire et du cadre de coopération. Elles sont précisées avant toute intervention.</p></details></div></div></section>
<section class="actions-final"><div class="agency-shell actions-final-card"><p class="agency-kicker">Passer à l'action</p><h2>Un bien vacant, une ressource ou un projet à nous présenter ?</h2><p>Territoires Vivants France étudie les situations pouvant contribuer à la remise en usage du patrimoine, à la revitalisation des quartiers et au développement d'activités utiles.</p><div class="agency-actions"><a class="agency-btn" href="contact">Signaler un bien</a><a class="agency-btn agency-btn-alt" href="contact">Présenter un projet</a><a class="agency-btn agency-btn-ghost" href="entreprises">Devenir partenaire</a></div></div></section>
<section class="agency-section"><div class="agency-shell narrow"><p class="agency-kicker">Coordonnées</p><h2>Présenter une action à TVF</h2><p><strong>Territoires Vivants France</strong><br>Agence Territoriale de Revitalisation Immobilière<br>${contact.address}<br>Téléphone : <a href="tel:${contact.phoneHref}">${contact.phone}</a><br>E-mail : <a href="mailto:${contact.email}">${contact.email}</a></p></div></section>`; }
function observatoryPage(){ return `<section class="observatory-hero"><div class="agency-shell observatory-hero-grid"><div class="observatory-hero-card"><p class="agency-kicker">Observatoire territorial</p><h1>Observer la vacance pour mieux agir sur les territoires.</h1><p>L'Observatoire de Territoires Vivants France rassemble, organise et analyse les informations utiles à la compréhension des logements vacants, commerces fermés, bâtiments délaissés, friches et terrains sans usage.</p><p>Il permet de mieux identifier les situations territoriales, d'orienter les actions de l'Agence et de faciliter la construction de réponses adaptées avec les propriétaires, collectivités et partenaires compétents.</p><div class="agency-actions"><a class="agency-btn" href="#observatoire-carte">Explorer l'Observatoire</a><a class="agency-btn agency-btn-alt" href="contact">Signaler une situation</a></div><p class="observatory-hero-note">Les données publiques sont présentées sous une forme générale ou anonymisée. Le signalement d'un bien ne permet pas, à lui seul, de confirmer juridiquement sa vacance.</p></div><div class="observatory-map-card"><div class="map-top"><span>Saint-Étienne</span><strong>Territoire pilote</strong></div><div class="map-area"><i class="pin pin-a"></i><i class="pin pin-b"></i><i class="pin pin-c"></i><i class="zone zone-a"></i><i class="zone zone-b"></i></div><div class="map-panel"><span>Filtres</span><b>Type · Statut · Période</b><em>Données anonymisées</em></div></div></div></section>
<section class="observatory-intro"><div class="agency-shell"><div class="observatory-intro-copy"><p class="agency-kicker">Connaissance territoriale</p><h2>Un outil de connaissance au service de la revitalisation</h2><p>La vacance immobilière recouvre des réalités très différentes. Un bien peut être temporairement inoccupé, en travaux, concerné par une succession, proposé à la vente, inhabitable, abandonné en apparence ou simplement fermé depuis une période limitée.</p><p>L'Observatoire TVF ne se contente donc pas de comptabiliser des adresses. Il cherche à comprendre les situations, leur évolution et leur environnement territorial.</p><p>Les informations recueillies permettent progressivement d'identifier les secteurs concernés, de distinguer les types de biens, de comprendre les causes connues ou supposées, de suivre les démarches engagées, de mobiliser les acteurs adaptés et d'évaluer l'évolution des actions conduites.</p></div><div class="observatory-method-line"><span>Repérer</span><span>Qualifier</span><span>Cartographier</span><span>Analyser</span><span>Orienter</span></div></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Biens et espaces observés</p><h2>Ce que l'Observatoire peut suivre</h2></div><div class="agency-shell observatory-type-grid"><article><img src="${photos.habitat}" alt="Logements vacants"><h3>Logements vacants</h3><p>Maisons, appartements, immeubles ou logements durablement inoccupés pouvant nécessiter une analyse complémentaire.</p><a href="nos-actions">Voir les indicateurs Habitat</a></article><article><img src="${photos.commerce}" alt="Locaux commerciaux"><h3>Locaux commerciaux</h3><p>Boutiques, cellules commerciales, rez-de-chaussée et locaux professionnels apparemment fermés ou sans activité connue.</p><a href="nos-actions">Voir les indicateurs Commerce</a></article><article><img src="${photos.ville}" alt="Bâtiments délaissés"><h3>Bâtiments délaissés</h3><p>Bâtiments privés ou publics sans usage apparent, anciens ateliers, bureaux, entrepôts ou ensembles dégradés.</p><a href="nos-actions">Voir les bâtiments observés</a></article><article><img src="${photos.friches}" alt="Friches"><h3>Friches</h3><p>Anciens sites industriels, économiques, artisanaux ou urbains dont l'usage initial a cessé ou fortement diminué.</p><a href="nos-actions">Voir les indicateurs Friches</a></article><article><img src="${photos.friches}" alt="Terrains sans usage"><h3>Terrains sans usage identifié</h3><p>Parcelles délaissées, terrains insuffisamment valorisés ou espaces pouvant présenter un potentiel territorial.</p><a href="nos-actions">Voir les indicateurs Foncier</a></article><article><img src="${photos.materiaux}" alt="Ressources réemployables"><h3>Ressources réemployables</h3><p>Matériaux, équipements, stocks ou éléments d'aménagement pouvant être mobilisés dans des projets suivis par TVF.</p><a href="entreprises">Découvrir le suivi du réemploi</a></article></div></section>
<section id="observatoire-carte" class="observatory-map-section"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Carte de l'Observatoire</p><h2>Explorer les dynamiques territoriales</h2></div><div class="observatory-map-layout"><div class="public-map"><div class="public-map-grid"><span></span><span></span><span></span><span></span></div><i class="pin pin-a"></i><i class="pin pin-b"></i><i class="pin pin-c"></i><strong>Saint-Étienne · secteur pilote</strong></div><aside class="observatory-filters"><h3>Filtres prévus</h3><p>Territoire : région, département, intercommunalité, commune, quartier ou secteur d'observation.</p><p>Type : logement, commerce, bâtiment, friche, terrain ou ressource.</p><p>État : signalé, à vérifier, en qualification, propriétaire contacté, étude engagée, projet en cours, remis en usage ou classé sans suite.</p><p>Niveau : information générale, signalement reçu, situation vérifiée, dossier actif ou action engagée.</p><p>Période : année du signalement, dernière mise à jour ou durée d'observation connue.</p></aside></div><p class="observatory-map-note">La carte publique n'a pas vocation à constituer un fichier nominatif des propriétaires ou une liste détaillée des adresses privées. Les informations relatives aux biens privés peuvent être regroupées, approximatives, anonymisées, limitées à des indicateurs statistiques ou réservées aux utilisateurs habilités.</p></div></section>
<section class="observatory-status"><div class="agency-shell observatory-status-grid"><div><p class="agency-kicker">Phase actuelle — structuration</p><h2>Un Observatoire en cours de déploiement</h2><p>Territoires Vivants France structure actuellement les méthodes, catégories et outils nécessaires au fonctionnement de son Observatoire territorial. Le premier déploiement est organisé autour du territoire pilote de Saint-Étienne.</p><p>Cette phase doit permettre de tester progressivement le formulaire de signalement, les fiches de qualification, la classification des biens, les niveaux de priorité, la cartographie, le suivi des dossiers, la mise à jour des informations, les modalités de coopération avec les collectivités et l'intégration des données dans TVF OS.</p><p>Les cartes, chiffres et résultats seront publiés à mesure que les informations seront vérifiées et suffisamment consolidées.</p></div><div class="dashboard-illustration"><span>Signalements</span><span>Qualification</span><span>Carte</span><span>TVF OS</span></div></div></section>
<section class="observatory-indicators"><div class="agency-shell"><p class="agency-kicker">Indicateurs</p><h2>Des indicateurs pour suivre la vacance et l'action territoriale</h2><p>L'Observatoire a vocation à produire des indicateurs permettant de mieux comprendre les situations observées et de suivre les actions engagées. Les indicateurs ne seront publiés qu'après vérification, consolidation et anonymisation des informations concernées.</p><div class="observatory-indicator-grid"><article><strong>Donnée en cours de consolidation</strong><span>Biens signalés</span></article><article><strong>Donnée en cours de consolidation</strong><span>Situations qualifiées</span></article><article><strong>Donnée en cours de consolidation</strong><span>Propriétaires contactés</span></article><article><strong>Donnée en cours de consolidation</strong><span>Dossiers orientés</span></article><article><strong>Donnée en cours de consolidation</strong><span>Projets engagés</span></article><article><strong>Donnée en cours de consolidation</strong><span>Remises en usage</span></article><article><strong>Donnée en cours de consolidation</strong><span>Ressources réemployées</span></article><article><strong>Donnée en cours de consolidation</strong><span>Délais de traitement</span></article></div></div></section>
<section class="observatory-process"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Qualification</p><h2>Du signalement à la qualification du dossier</h2></div><ol class="observatory-steps"><li><strong>Réception</strong><span>Une situation est transmise par un propriétaire, habitant, collectivité, entreprise, association ou partenaire.</span></li><li><strong>Enregistrement</strong><span>Les premières informations sont enregistrées et un numéro de signalement ou dossier peut être attribué.</span></li><li><strong>Vérification préliminaire</strong><span>TVF vérifie la cohérence sans conclure immédiatement à la vacance ou à l'abandon.</span></li><li><strong>Classification</strong><span>Type de bien, source, état apparent, niveau d'information, démarches et priorité.</span></li><li><strong>Compléments</strong><span>Recherche d'éléments légalement accessibles ou sollicitation d'acteurs habilités.</span></li><li><strong>Orientation</strong><span>Parcours propriétaire, collectivité, commerce, friche, foncier, réemploi, solidarité ou partenaire spécialisé.</span></li><li><strong>Mise à jour</strong><span>Le statut évolue selon les échanges, vérifications et actions réalisées.</span></li></ol></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Niveaux de qualification</p><h2>Des statuts clairs pour éviter les conclusions hâtives</h2></div><div class="agency-shell qualification-grid"><article><span>Niveau 1</span><h3>Signalement reçu</h3><p>Une information a été transmise, mais elle n'a pas encore été vérifiée.</p></article><article><span>Niveau 2</span><h3>Situation à examiner</h3><p>Les éléments transmis paraissent cohérents, mais des informations complémentaires sont nécessaires.</p></article><article><span>Niveau 3</span><h3>Situation qualifiée</h3><p>La nature du bien et les principaux éléments ont été vérifiés dans la limite des informations accessibles.</p></article><article><span>Niveau 4</span><h3>Démarche engagée</h3><p>Un échange, une orientation, une visite ou une action a été engagé.</p></article><article><span>Niveau 5</span><h3>Projet suivi</h3><p>La situation fait l'objet d'un accompagnement ou d'un suivi opérationnel.</p></article><article><span>Clôture</span><h3>Dossier clôturé</h3><p>Remis en usage, orienté vers un autre acteur, retiré, classé sans suite ou sans intervention supplémentaire possible.</p></article></div></section>
<section class="observatory-report"><div class="agency-shell observatory-report-grid"><div><p class="agency-kicker">Signalement</p><h2>Vous avez repéré un bien ou un espace apparemment vacant ?</h2><p>Un propriétaire, un habitant, une association, une entreprise ou une collectivité peut transmettre un signalement à TVF. Le signalement attire l'attention de l'Agence sur une situation. Il ne constitue ni une preuve juridique de vacance, ni une déclaration d'abandon, ni une procédure administrative.</p><ul><li>Adresse ou localisation du bien.</li><li>Type de bien et état apparent.</li><li>Durée d'inoccupation supposée.</li><li>Photographies prises depuis l'espace public.</li><li>Observations utiles, identité et coordonnées du déclarant.</li><li>Lien éventuel avec le bien et accord pour être recontacté.</li></ul><a class="agency-btn" href="contact">Signaler une situation</a><p class="observatory-small-note">Un signalement peut être conservé, complété, orienté ou classé sans suite selon les informations disponibles et les priorités de l'Agence.</p></div><div class="report-preview"><span>Formulaire</span><b>Type de bien</b><b>Localisation</b><b>Observations</b><b>Photos autorisées</b></div></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Sources</p><h2>Des informations provenant de plusieurs sources</h2></div><div class="agency-shell source-network"><div class="source-center">Observatoire TVF</div><article>Propriétaires</article><article>Collectivités</article><article>Habitants</article><article>Entreprises et associations</article><article>Observations de TVF</article><article>Sources légalement accessibles</article></div><div class="agency-shell observatory-note"><p>Certaines bases administratives, fiscales, cadastrales ou foncières ne sont pas librement accessibles. TVF ne prétend pas disposer d'un accès direct à des fichiers réservés aux autorités ou organismes habilités.</p></div></section>
<section class="observatory-partners"><div class="agency-shell observatory-partners-grid"><div><p class="agency-kicker">Espace professionnel</p><h2>Un espace de suivi pour les partenaires autorisés</h2><p>Dans le cadre d'une coopération formalisée, une collectivité ou un partenaire peut disposer d'un accès adapté à son rôle et au périmètre de la mission.</p><p>Cet espace pourra permettre de transmettre des signalements, suivre les situations relevant du partenariat, consulter une cartographie dédiée, visualiser les statuts, déposer des documents, transmettre des observations, consulter les comptes rendus, exporter des synthèses et suivre les indicateurs du territoire.</p><p>Les droits d'accès sont définis selon le principe du besoin d'en connaître.</p><div class="agency-actions"><a class="agency-btn" href="collectivites">Construire un Observatoire local</a><a class="agency-btn agency-btn-alt" href="contact">Demander une présentation de TVF OS</a></div></div><div class="os-preview"><span>TVF OS</span><b>Demandes</b><b>Dossiers</b><b>Carte</b><b>Documents</b><b>Indicateurs</b></div></div></section>
<section class="observatory-dashboard"><div class="agency-shell"><div class="section-title"><p class="agency-kicker">Tableau de bord public</p><h2>Une interface publique lorsque les données seront consolidées</h2></div><div class="dashboard-shell"><aside><span>Filtres</span><b>Territoire</b><b>Type</b><b>Période</b></aside><main><strong>Carte et graphiques publics</strong><p>Les premiers tableaux de bord seront publiés après la consolidation des données du territoire pilote.</p></main><aside><span>Tendances</span><b>Habitat</b><b>Commerce</b><b>Friches</b><b>Réemploi</b></aside></div><p class="observatory-note-text">Aucun graphique n'est rempli avec des chiffres fictifs uniquement pour donner l'impression que la plateforme fonctionne déjà.</p></div></section>
<section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Publications</p><h2>Comprendre les dynamiques locales</h2></div><div class="agency-shell publication-grid"><article><span>En préparation</span><h3>Méthode de qualification des signalements</h3><p>Présentation des catégories, niveaux de vérification et règles d'orientation des dossiers.</p><a href="ressources">Voir les ressources</a></article><article><span>À venir</span><h3>Diagnostic initial du territoire pilote</h3><p>Première analyse territoriale produite à partir des informations suffisamment vérifiées.</p><a href="saint-etienne">Voir Saint-Étienne</a></article><article><span>Publication future</span><h3>Bilan annuel de l'Observatoire</h3><p>Présentation des résultats consolidés, limites méthodologiques et actions engagées.</p><a href="impact">Voir l'impact</a></article></div></section>
<section class="observatory-privacy"><div class="agency-shell observatory-privacy-grid"><div>${icon('D')}</div><div><p class="agency-kicker">Données et confidentialité</p><h2>Observer sans exposer</h2><p>L'Observatoire TVF distingue les informations pouvant être rendues publiques des informations réservées au traitement interne ou aux partenaires autorisés.</p><div class="privacy-columns"><article><h3>Données publiques</h3><p>Statistiques générales, tendances territoriales, cartes agrégées, résultats anonymisés, indicateurs par catégorie et bilans d'action.</p></article><article><h3>Données à accès restreint</h3><p>Coordonnées des propriétaires, adresses précises de certains biens privés, documents, échanges, photographies non publiables et informations contractuelles.</p></article></div><p>TVF veille à limiter la collecte, préciser la finalité, contrôler les accès, sécuriser les dossiers, limiter la conservation, permettre l'exercice des droits, anonymiser les données publiées et corriger les informations inexactes signalées.</p><div class="agency-actions"><a class="agency-btn" href="politique-confidentialite">Consulter la politique de confidentialité</a><a class="agency-btn agency-btn-alt" href="contact">Exercer mes droits</a></div></div></div></section>
<section class="observatory-limits"><div class="agency-shell limits-card"><p class="agency-kicker">À savoir</p><h2>Ce que l'Observatoire ne permet pas d'affirmer</h2><p>La présence d'un bien dans les outils internes ou statistiques de l'Observatoire ne signifie pas automatiquement qu'il est juridiquement abandonné, sans propriétaire, inhabitable, disponible, visitable, que TVF peut en disposer, qu'une procédure administrative est engagée ou qu'un projet sera nécessairement réalisé.</p><p>L'Observatoire constitue un outil de connaissance et d'orientation. Les décisions relevant du droit de propriété, de l'urbanisme, de la sécurité, de la fiscalité ou des pouvoirs publics appartiennent aux personnes et autorités compétentes.</p></div></section>
<section class="owner-faq observatory-faq"><div class="agency-shell owner-faq-grid"><div><p class="agency-kicker">Questions fréquentes</p><h2>Comprendre l'Observatoire</h2></div><div class="owner-accordion"><details><summary>Existe-t-il un registre public national recensant tous les logements vacants ?</summary><p>Il existe plusieurs sources administratives, fiscales et territoriales, mais elles ne constituent pas toutes un registre public librement accessible. Leur accès dépend de la nature des données et de l'habilitation du demandeur.</p></details><details><summary>Une personne peut-elle consulter l'adresse de tous les biens signalés ?</summary><p>Non. Les adresses précises et les informations relatives aux propriétaires ne sont pas destinées à être librement diffusées.</p></details><details><summary>Comment savoir si un bien est réellement vacant ?</summary><p>Un signalement doit être complété par des vérifications. Un logement fermé ou apparemment inoccupé n'est pas nécessairement durablement vacant.</p></details><details><summary>Puis-je signaler un bien dont je ne suis pas propriétaire ?</summary><p>Oui, à condition de transmettre des observations réalisées légalement et de ne pas pénétrer dans la propriété.</p></details><details><summary>Le propriétaire est-il informé du signalement ?</summary><p>La prise de contact dépend du niveau de qualification, du cadre applicable, des informations disponibles et de la suite donnée au dossier.</p></details><details><summary>Puis-je demander la suppression ou la correction d'une information ?</summary><p>Toute personne concernée peut contacter TVF pour signaler une erreur ou exercer les droits applicables à ses données personnelles.</p></details><details><summary>Les données de l'Observatoire sont-elles en temps réel ?</summary><p>Non. Les informations nécessitent des vérifications et des mises à jour. La date de mise à jour doit être indiquée sur chaque tableau de bord ou publication.</p></details><details><summary>Une collectivité peut-elle créer son propre tableau de bord avec TVF ?</summary><p>Oui, une coopération peut être étudiée et formalisée selon le territoire, les objectifs, les données disponibles et les responsabilités de chaque partie.</p></details></div></div></section>
<section class="observatory-final"><div class="agency-shell observatory-final-card"><p class="agency-kicker">Agir avec l'Observatoire</p><h2>Une meilleure connaissance pour des actions plus justes</h2><p>Vous souhaitez signaler une situation, présenter des données territoriales ou construire un Observatoire local avec Territoires Vivants France ? Notre équipe étudie votre demande et l'oriente vers le parcours correspondant.</p><div class="agency-actions"><a class="agency-btn" href="contact">Signaler un bien ou un espace</a><a class="agency-btn agency-btn-alt" href="collectivites">Présenter un territoire</a><a class="agency-btn agency-btn-ghost" href="mailto:${contact.email}">Contacter l'Observatoire</a></div></div></section>
<section class="agency-section"><div class="agency-shell narrow"><p class="agency-kicker">Coordonnées</p><h2>Contacter l'Observatoire TVF</h2><p><strong>Territoires Vivants France</strong><br>Agence Territoriale de Revitalisation Immobilière<br>${contact.address}<br>Téléphone : <a href="tel:${contact.phoneHref}">${contact.phone}</a><br>E-mail : <a href="mailto:${contact.email}">${contact.email}</a><br>Site : <a href="${site.url}">www.territoiresvivantsfrance.fr</a></p></div></section>`; }
function contactPage(){ return `<section class="contact-hero"><div class="agency-shell contact-hero-grid"><div class="contact-hero-card"><p class="agency-kicker">Contacter l'Agence</p><h1>Parlons de votre bien, de votre territoire ou de votre projet.</h1><p>Vous êtes propriétaire, représentant d'une collectivité, entreprise, association ou porteur de projet ?</p><p>L'équipe de Territoires Vivants France vous accompagne dans l'orientation de votre demande et vous aide à identifier le parcours correspondant à votre situation.</p><div class="agency-actions"><a class="agency-btn" href="#contact-form">Nous écrire</a><a class="agency-btn agency-btn-alt" href="tel:${contact.phoneHref}">Demander à être rappelé</a></div><p class="contact-hero-note">Chaque demande est étudiée avant d'être orientée vers le pôle ou l'interlocuteur compétent.</p></div><figure><img src="${photos.hero}" alt="Centre-ville de Saint-Étienne et territoire pilote"><figcaption>Saint-Étienne · territoire pilote de l'Agence</figcaption></figure></div></section>
<section class="contact-motives"><div class="agency-shell section-title"><p class="agency-kicker">Votre besoin</p><h2>Choisir le motif de sa demande</h2></div><div class="agency-shell contact-motive-grid"><a class="contact-route-card" href="#contact-form" data-contact-profile="Propriétaire particulier" data-contact-category="Présenter un bien vacant">${icon('P')}<h3>Je suis propriétaire</h3><p>Vous souhaitez présenter un logement, un commerce, un bâtiment, une friche ou un terrain vacant.</p><span>Présenter mon bien</span></a><a class="contact-route-card" href="#contact-form" data-contact-profile="Collectivité" data-contact-category="Construire un partenariat territorial">${icon('C')}<h3>Je représente une collectivité</h3><p>Vous souhaitez organiser une démarche de repérage, d'observation ou de revitalisation sur votre territoire.</p><span>Présenter mon territoire</span></a><a class="contact-route-card" href="#contact-form" data-contact-profile="Entreprise" data-contact-category="Proposer des matériaux ou équipements">${icon('E')}<h3>Je représente une entreprise</h3><p>Vous souhaitez proposer des matériaux, une expertise, un partenariat ou un soutien.</p><span>Proposer une contribution</span></a><a class="contact-route-card" href="#contact-form" data-contact-profile="Habitant" data-contact-category="Signaler un bien ou un espace">${icon('S')}<h3>Je souhaite signaler une situation</h3><p>Vous avez repéré un bien ou un espace apparemment vacant ou délaissé.</p><span>Effectuer un signalement</span></a><a class="contact-route-card" href="#contact-form" data-contact-profile="Porteur de projet" data-contact-category="Présenter un projet">${icon('A')}<h3>Je porte un projet</h3><p>Vous souhaitez présenter une activité, une initiative associative, commerciale, solidaire ou territoriale.</p><span>Présenter mon projet</span></a><a class="contact-route-card" href="#contact-form" data-contact-profile="Autre" data-contact-category="Autre demande">${icon('?')}<h3>J'ai une demande générale</h3><p>Vous souhaitez poser une question sur TVF, son fonctionnement ou ses actions.</p><span>Contacter l'Agence</span></a></div></section>
<section class="contact-main"><div class="agency-shell contact-main-grid"><div class="contact-form-card">${contactFormHtml()}</div><aside class="contact-side-card"><h2>Contacter Territoires Vivants France</h2><p><strong>Agence Territoriale de Revitalisation Immobilière</strong></p><p>${contact.address}</p><p><a href="tel:${contact.phoneHref}">${contact.phone}</a><br><a href="mailto:${contact.email}">${contact.email}</a><br><a href="${site.url}">www.territoiresvivantsfrance.fr</a></p><hr><h3>Accueil</h3><p>L'accueil s'effectue actuellement principalement par e-mail et sur rendez-vous. Les horaires téléphoniques seront publiés dès leur stabilisation.</p><a class="agency-btn agency-btn-alt" href="#contact-form">Demander un rendez-vous</a><h3>Visite d'un bien</h3><p>Aucune visite n'est organisée sans échange préalable, accord du propriétaire ou de son représentant et validation des conditions d'intervention.</p></aside></div></section>
<section class="contact-treatment"><div class="agency-shell contact-treatment-grid"><div><p class="agency-kicker">Traitement</p><h2>Comment votre demande est-elle traitée ?</h2><p>Les délais peuvent varier selon la nature de la demande, les informations disponibles et les priorités de traitement.</p></div><ol><li><strong>Réception</strong><span>Votre demande est enregistrée et reçoit une référence.</span></li><li><strong>Lecture</strong><span>L'équipe vérifie les informations transmises et la nature du besoin.</span></li><li><strong>Orientation</strong><span>La demande est affectée au pôle ou au parcours correspondant.</span></li><li><strong>Prise de contact</strong><span>Un échange complémentaire peut être proposé.</span></li><li><strong>Dossier éventuel</strong><span>Lorsque la situation nécessite un suivi, un dossier distinct peut être créé dans les outils de TVF.</span></li></ol></div></section>
<section class="contact-warning"><div class="agency-shell"><h2>Une situation présente un danger immédiat ?</h2><p>Territoires Vivants France n'est pas un service d'urgence. En cas de danger immédiat pour les personnes, d'incendie, d'effondrement, d'intrusion en cours, de fuite importante ou de risque pour la voie publique, contactez directement les services d'urgence ou les autorités compétentes.</p><p>Pour une situation liée à l'insalubrité, à la sécurité d'un immeuble ou à l'occupation du domaine public, vous pouvez également contacter la mairie ou le service compétent de votre commune.</p></div></section>
<section class="contact-location"><div class="agency-shell contact-location-grid"><div class="contact-map-card"><span>Saint-Étienne</span><strong>25 rue Élise Gervais</strong><i></i></div><div><p class="agency-kicker">Localisation</p><h2>Nous trouver</h2><p>Territoires Vivants France est implantée à Saint-Étienne, territoire pilote de l'Agence.</p><p><strong>Adresse :</strong><br>${contact.address}</p><p>Accueil uniquement sur rendez-vous. La carte ne doit pas afficher d'autres agences ou implantations tant qu'elles ne sont pas réellement ouvertes.</p></div></div></section>
<section class="contact-special"><div class="agency-shell"><p class="agency-kicker">Contacts spécialisés</p><h2>Une adresse unique pour toutes les demandes</h2><p>Pour éviter les erreurs d'orientation, toutes les demandes sont actuellement centralisées à l'adresse : <a href="mailto:${contact.email}">${contact.email}</a>.</p></div></section>
<section class="owner-faq contact-faq"><div class="agency-shell owner-faq-grid"><div><p class="agency-kicker">Questions fréquentes</p><h2>Avant de nous écrire</h2></div><div class="owner-accordion"><details><summary>Dois-je être propriétaire pour contacter TVF ?</summary><p>Non. Les collectivités, entreprises, associations, habitants et porteurs de projets peuvent également transmettre une demande.</p></details><details><summary>Puis-je envoyer des documents dès le premier contact ?</summary><p>Oui, lorsque ces documents sont utiles. Il est toutefois préférable de ne transmettre que les pièces nécessaires.</p></details><details><summary>Puis-je venir directement à l'adresse de TVF ?</summary><p>L'accueil se fait sur rendez-vous afin de garantir la disponibilité d'un interlocuteur adapté à votre demande.</p></details><details><summary>Comment signaler un logement vacant ?</summary><p>Sélectionnez le motif « Signaler un bien ou un espace » dans le formulaire et transmettez les informations dont vous disposez.</p></details><details><summary>Puis-je suivre ma demande ?</summary><p>Un numéro de référence peut être communiqué après l'envoi. Le suivi en ligne pourra être activé progressivement avec TVF OS.</p></details><details><summary>TVF répond-elle à toutes les demandes ?</summary><p>Chaque demande est examinée. Elle peut être acceptée, complétée, orientée vers un autre organisme ou classée sans suite lorsque TVF n'est pas compétente ou ne dispose pas des moyens nécessaires.</p></details><details><summary>Puis-je demander une visite du bien ?</summary><p>Oui, mais une visite n'est jamais automatique. Elle dépend de la situation, de l'accord du propriétaire et de la validation préalable de TVF.</p></details><details><summary>Mes informations seront-elles publiques ?</summary><p>Non. Les données personnelles et les documents transmis ne sont pas destinés à être publiés. Leur traitement doit respecter la politique de confidentialité de TVF.</p></details></div></div></section>
<section class="contact-final"><div class="agency-shell contact-final-card"><p class="agency-kicker">Entrée unique</p><h2>Votre demande mérite le bon interlocuteur</h2><p>Présentez votre situation à Territoires Vivants France. Notre équipe l'étudiera afin de vous orienter vers le parcours adapté.</p><div class="agency-actions"><a class="agency-btn" href="#contact-form">Présenter un bien</a><a class="agency-btn agency-btn-alt" href="collectivites">Présenter un territoire</a><a class="agency-btn agency-btn-ghost" href="entreprises">Proposer un partenariat</a></div></div></section>`; }
function saintEtiennePage(){ return `<section class="info-hero"><div class="agency-shell info-hero-grid"><div><p class="agency-kicker">Territoire pilote</p><h1>Saint-&Eacute;tienne, premier terrain d'application de la m&eacute;thode TVF.</h1><p>Le territoire pilote permet de tester une m&eacute;thode simple : rep&eacute;rer les biens vacants, qualifier les situations, dialoguer avec les propri&eacute;taires, rechercher les bons interlocuteurs et suivre les dossiers dans TVF OS.</p><div class="agency-actions"><a class="agency-btn" href="contact">Pr&eacute;senter une situation</a><a class="agency-btn agency-btn-alt" href="observatoire">Voir l'Observatoire</a></div></div><figure><img src="${photos.hero}" alt="Saint-Etienne, territoire pilote"></figure></div></section><section class="agency-section"><div class="agency-shell info-grid"><article><p class="agency-kicker">Pourquoi Saint-&Eacute;tienne ?</p><h2>Un territoire adapt&eacute; pour structurer une premi&egrave;re m&eacute;thode.</h2><p>Saint-&Eacute;tienne pr&eacute;sente des enjeux de centre-ville, de commerces vacants, de logements anciens, de b&acirc;timents &agrave; requalifier et de ressources &agrave; mieux valoriser. TVF y d&eacute;veloppe une approche de terrain, progressive et document&eacute;e.</p><p>Le site ne pr&eacute;sente pas de partenariat institutionnel comme acquis tant qu'il n'a pas &eacute;t&eacute; formalis&eacute;. Les informations publi&eacute;es restent limit&eacute;es aux &eacute;l&eacute;ments v&eacute;rifi&eacute;s.</p></article><article><p class="agency-kicker">Ce qui peut &ecirc;tre observ&eacute;</p><h2>Des situations concr&egrave;tes &agrave; qualifier.</h2><ul><li>Logements ferm&eacute;s ou d&eacute;grad&eacute;s.</li><li>Locaux commerciaux inoccup&eacute;s.</li><li>B&acirc;timents sans usage apparent.</li><li>Terrains ou friches &agrave; comprendre.</li><li>Stocks de mat&eacute;riaux ou &eacute;quipements disponibles.</li></ul></article></div></section><section class="agency-section soft"><div class="agency-shell section-title"><p class="agency-kicker">Exemples de projets &eacute;tudiables</p><h2>Des id&eacute;es, pas des promesses.</h2></div><div class="agency-shell info-card-grid"><article><h3>Logement vacant</h3><p>&Eacute;tude d'une remise en usage pour location, habitat temporaire, logement &eacute;tudiant ou autre solution compatible avec le bien.</p></article><article><h3>Commerce ferm&eacute;</h3><p>Recherche d'un usage possible : artisanat, service de proximit&eacute;, local associatif, activit&eacute; temporaire ou commerce adapt&eacute; au secteur.</p></article><article><h3>B&acirc;timent inutilis&eacute;</h3><p>Premi&egrave;re qualification, identification des contraintes et orientation vers les acteurs comp&eacute;tents.</p></article><article><h3>Mat&eacute;riaux disponibles</h3><p>R&eacute;emploi possible dans un projet suivi, sous r&eacute;serve d'&eacute;tat, de stockage, de transport et d'utilit&eacute; r&eacute;elle.</p></article></div></section><section class="agency-section"><div class="agency-shell info-grid"><article><p class="agency-kicker">Premiers travaux &agrave; mener</p><h2>Une installation progressive.</h2><ol><li>Centraliser les signalements et demandes.</li><li>Cr&eacute;er les fiches de qualification.</li><li>Identifier les propri&eacute;taires ou repr&eacute;sentants connus.</li><li>Approcher les acteurs publics, techniques et &eacute;conomiques.</li><li>Rechercher un local de stockage adapt&eacute; aux mat&eacute;riaux.</li><li>Structurer les conventions et pi&egrave;ces &agrave; fournir.</li></ol></article><article><p class="agency-kicker">Suivi</p><h2>Chaque situation doit devenir lisible.</h2><p>TVF OS sert &agrave; rattacher une demande &agrave; un contact, puis &agrave; un dossier lorsque la situation n&eacute;cessite un suivi. Les statuts permettent de distinguer signalement, qualification, orientation, dossier actif et cl&ocirc;ture.</p><a class="agency-btn" href="tvf-os">Comprendre TVF OS</a></article></div></section>`; }
function partnersPage(){ return `<section class="info-hero"><div class="agency-shell info-hero-grid"><div><p class="agency-kicker">Partenaires</p><h1>Construire des coop&eacute;rations utiles, claires et encadr&eacute;es.</h1><p>TVF recherche des partenaires capables de contribuer &agrave; la remise en usage des biens vacants, &agrave; la valorisation des ressources et &agrave; la construction de projets territoriaux.</p><div class="agency-actions"><a class="agency-btn" href="contact">Proposer une coop&eacute;ration</a><a class="agency-btn agency-btn-alt" href="entreprises">Voir le parcours entreprises</a></div></div><figure><img src="${photos.solidarite}" alt="Cooperation territoriale"></figure></div></section><section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Types de partenaires recherch&eacute;s</p><h2>Un r&ocirc;le diff&eacute;rent selon chaque acteur.</h2></div><div class="agency-shell info-card-grid"><article><h3>Collectivit&eacute;s</h3><p>Rep&eacute;rage, observation, connaissance territoriale, priorisation et coop&eacute;ration locale.</p></article><article><h3>Entreprises</h3><p>Mat&eacute;riaux, &eacute;quipements, expertise, stockage, transport, comp&eacute;tences ou soutien financier.</p></article><article><h3>Associations</h3><p>Projets d'usage, besoins locaux, insertion, solidarit&eacute;, animation de quartier ou activit&eacute; utile.</p></article><article><h3>Professionnels habilit&eacute;s</h3><p>Diagnostics, travaux, architecture, foncier, droit, gestion, s&eacute;curit&eacute; ou accompagnement r&eacute;glement&eacute;.</p></article><article><h3>Fondations et financeurs</h3><p>Soutien &agrave; des projets cadr&eacute;s, budgets, conventions et indicateurs de suivi.</p></article><article><h3>Propri&eacute;taires</h3><p>Mise &agrave; l'&eacute;tude d'un bien vacant, conventionnement ou recherche d'une solution adapt&eacute;e.</p></article></div></section><section class="agency-section soft"><div class="agency-shell info-grid"><article><p class="agency-kicker">Cadre</p><h2>Aucun partenariat n'est automatique.</h2><p>Chaque coop&eacute;ration fait l'objet d'un &eacute;change pr&eacute;alable. Lorsque cela est n&eacute;cessaire, une convention pr&eacute;cise l'objectif, la dur&eacute;e, les responsabilit&eacute;s, les moyens, les donn&eacute;es partag&eacute;es et les conditions de communication.</p></article><article><p class="agency-kicker">Transparence</p><h2>Pas de faux logos, pas de faux r&eacute;sultats.</h2><p>TVF ne publie pas de partenaire comme acquis sans accord explicite. Les contributions, r&eacute;sultats et indicateurs sont pr&eacute;sent&eacute;s apr&egrave;s validation.</p><a class="agency-btn" href="contact">&Eacute;changer avec TVF</a></article></div><section class="agency-section"><div class="agency-shell info-grid"><article><p class="agency-kicker">Modalites de cooperation</p><h2>Des formes souples, mais toujours cadr&eacute;es.</h2><p>Une cooperation peut prendre la forme d'un rendez-vous exploratoire, d'une convention de partenariat, d'une mise a disposition, d'un don de materiaux, d'un soutien financier, d'une orientation technique ou d'un accompagnement ponctuel.</p><p>Le niveau d'engagement depend du besoin identifie, des moyens disponibles, du cadre juridique et de la validation des parties.</p></article><article><p class="agency-kicker">Ce que TVF attend</p><h2>Des contributions utiles, pas symboliques.</h2><ul><li>Un interlocuteur clairement identifie.</li><li>Une contribution reliee a un besoin territorial.</li><li>Des conditions de mise en oeuvre realistes.</li><li>Une communication validee par les parties.</li><li>Un suivi proportionne a l'action menee.</li></ul></article></div></section></section>`; }
function impactPage(){ return `<section class="info-hero"><div class="agency-shell info-hero-grid"><div><p class="agency-kicker">Impact</p><h1>Mesurer uniquement ce qui est v&eacute;rifi&eacute;.</h1><p>L'impact de TVF doit &ecirc;tre rattach&eacute; &agrave; des demandes, dossiers, conventions, ressources affect&eacute;es ou actions r&eacute;ellement suivies. Aucun chiffre n'est affich&eacute; comme r&eacute;sultat tant qu'il n'est pas consolid&eacute;.</p><div class="agency-actions"><a class="agency-btn" href="observatoire">Voir l'Observatoire</a><a class="agency-btn agency-btn-alt" href="contact">Pr&eacute;senter une action</a></div></div><figure><img src="${photos.ville}" alt="Indicateurs territoriaux"></figure></div></section><section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Indicateurs &agrave; suivre</p><h2>Les mesures pr&eacute;vues.</h2></div><div class="agency-shell impact-metric-grid"><article><strong>&Agrave; consolider</strong><span>Biens signal&eacute;s</span><p>Nombre de signalements re&ccedil;us par profil, territoire et cat&eacute;gorie.</p></article><article><strong>&Agrave; consolider</strong><span>Dossiers ouverts</span><p>Demandes transform&eacute;es en dossiers suivis dans TVF OS.</p></article><article><strong>&Agrave; consolider</strong><span>Propri&eacute;taires contact&eacute;s</span><p>D&eacute;marches de contact engag&eacute;es dans un cadre autoris&eacute;.</p></article><article><strong>&Agrave; consolider</strong><span>Conventions sign&eacute;es</span><p>Partenariats, mises &agrave; disposition, dons ou coop&eacute;rations formalis&eacute;es.</p></article><article><strong>&Agrave; consolider</strong><span>Mat&eacute;riaux affect&eacute;s</span><p>Ressources accept&eacute;es puis attribu&eacute;es &agrave; un projet identifi&eacute;.</p></article><article><strong>&Agrave; consolider</strong><span>Remises en usage</span><p>Situations ayant abouti &agrave; une occupation ou un nouvel usage v&eacute;rifi&eacute;.</p></article></div></section><section class="agency-section soft"><div class="agency-shell info-grid"><article><p class="agency-kicker">M&eacute;thode</p><h2>Un indicateur doit avoir une preuve.</h2><p>Chaque r&eacute;sultat doit pouvoir &ecirc;tre reli&eacute; &agrave; une date, un dossier, un territoire, une source interne ou une convention. Les donn&eacute;es publiques peuvent &ecirc;tre anonymis&eacute;es ou agr&eacute;g&eacute;es.</p></article><article><p class="agency-kicker">Limites</p><h2>Objectif ne signifie pas r&eacute;sultat.</h2><p>Les objectifs de d&eacute;ploiement, les projets en &eacute;tude et les r&eacute;sultats obtenus sont distingu&eacute;s afin d'&eacute;viter toute confusion.</p></article></div><section class="agency-section"><div class="agency-shell info-grid"><article><p class="agency-kicker">Publication progressive</p><h2>Des resultats publics quand ils sont consolid&eacute;s.</h2><p>La publication des resultats se fera par periode et par categorie afin de ne pas melanger les signalements, les dossiers ouverts, les projets orientes et les remises en usage effectives.</p><p>Chaque indicateur devra indiquer son perimetre, sa periode, sa methode de calcul et ses limites.</p></article><article><p class="agency-kicker">Utilite pour les partenaires</p><h2>Un impact lisible pour decider.</h2><p>Les collectivites, financeurs et entreprises partenaires pourront mieux comprendre les besoins identifies, les actions engagees et les suites donnees aux ressources ou soutiens mobilises.</p></article></div></section></section>`; }
function resourcesPage(){ return `<section class="info-hero"><div class="agency-shell info-hero-grid"><div><p class="agency-kicker">Ressources</p><h1>Retrouver les informations publiques utiles.</h1><p>Cette page oriente vers les contenus de r&eacute;f&eacute;rence du site. Les documents internes de gestion, mod&egrave;les et formulaires op&eacute;rationnels restent r&eacute;serv&eacute;s &agrave; TVF OS.</p><div class="agency-actions"><a class="agency-btn" href="faq">FAQ</a><a class="agency-btn agency-btn-alt" href="tvf-os">Comprendre TVF OS</a></div></div><figure><img src="${photos.ressources}" alt="Ressources et documents"></figure></div></section><section class="agency-section"><div class="agency-shell info-card-grid"><article><h3>FAQ</h3><p>R&eacute;ponses aux questions courantes avant de d&eacute;poser une demande.</p><a href="faq">Lire</a></article><article><h3>Kit m&eacute;dia</h3><p>Identit&eacute;, logo, informations administratives et contact presse.</p><a href="kit-media">Acc&eacute;der</a></article><article><h3>Mentions l&eacute;gales</h3><p>Informations administratives, &eacute;diteur du site, h&eacute;bergement et responsabilit&eacute;.</p><a href="mentions-legales">Consulter</a></article><article><h3>Confidentialit&eacute;</h3><p>Donn&eacute;es personnelles, finalit&eacute;s, conservation et droits.</p><a href="politique-confidentialite">Consulter</a></article><article><h3>Pi&egrave;ces &agrave; fournir</h3><p>Premi&egrave;re liste des documents utiles selon le profil et la demande.</p><a href="documents">Voir la liste</a></article><article><h3>Contact</h3><p>Entr&eacute;e unique pour orienter une demande vers le bon parcours.</p><a href="contact">Contacter TVF</a></article></div><section class="agency-section soft"><div class="agency-shell info-grid"><article><p class="agency-kicker">Ressources internes</p><h2>Ce qui n'est pas public.</h2><p>Les modeles de conventions, fiches internes, courriers, tableaux de suivi, pieces jointes et documents de gestion ne sont pas diffuses librement sur le site public.</p><p>Ils sont organises dans TVF OS afin de garder une tracabilite et d'eviter l'utilisation de documents non adaptes a une situation precise.</p></article><article><p class="agency-kicker">Ressources publiques</p><h2>Ce qui peut etre partage.</h2><p>Les informations institutionnelles, coordonnees, mentions legales, politique de confidentialite, FAQ et contenus de presentation peuvent etre transmis aux interlocuteurs publics, prives ou associatifs.</p><a class="agency-btn" href="contact">Demander une information</a></article></div></section><section class="agency-section"><div class="agency-shell info-grid"><article><p class="agency-kicker">Comment utiliser les ressources</p><h2>Commencer par le bon parcours.</h2><p>Un proprietaire doit d'abord consulter le parcours proprietaire et la liste des pieces utiles. Une entreprise doit consulter la page entreprises pour comprendre les contributions possibles. Une collectivite doit passer par le parcours collectivites pour cadrer le besoin territorial.</p></article><article><p class="agency-kicker">Mise a jour</p><h2>Des ressources appelees a evoluer.</h2><p>Les ressources publiques seront enrichies au fur et a mesure de la formalisation des documents, des methodes, des premiers retours d'experience et des informations administratives definitives.</p></article></div></section></section>`; }
function piecesPage(){ return `<section class="info-hero"><div class="agency-shell info-hero-grid"><div><p class="agency-kicker">Pi&egrave;ces &agrave; fournir</p><h1>Pr&eacute;parer une demande lisible d&egrave;s le premier contact.</h1><p>Les documents varient selon le profil, la nature du bien et le projet. Cette liste aide &agrave; pr&eacute;parer l'&eacute;tude sans transmettre de pi&egrave;ces inutiles.</p><div class="agency-actions"><a class="agency-btn" href="contact">D&eacute;poser une demande</a><a class="agency-btn agency-btn-alt" href="proprietaires">Parcours propri&eacute;taire</a></div></div><figure><img src="${photos.ressources}" alt="Documents et pieces utiles"></figure></div></section><section class="agency-section"><div class="agency-shell info-card-grid"><article><h3>Propri&eacute;taire particulier</h3><ul><li>Identit&eacute; et coordonn&eacute;es.</li><li>Adresse du bien.</li><li>Justificatif de qualit&eacute; &agrave; agir si disponible.</li><li>Photos prises l&eacute;galement.</li><li>Description de la situation et objectif recherch&eacute;.</li></ul></article><article><h3>Commerce ou local</h3><ul><li>Adresse et type de local.</li><li>Surface connue si disponible.</li><li>Situation d'occupation.</li><li>Contraintes ou travaux connus.</li><li>Usage envisag&eacute; ou attendu.</li></ul></article><article><h3>Friche, terrain ou b&acirc;timent</h3><ul><li>Localisation et rep&egrave;res cadastraux si connus.</li><li>Ancien usage suppos&eacute;.</li><li>Photos depuis l'espace public.</li><li>Contraintes connues.</li><li>Acteurs d&eacute;j&agrave; identifi&eacute;s.</li></ul></article><article><h3>Entreprise</h3><ul><li>Nom, SIRET et contact.</li><li>Nature de la contribution.</li><li>Quantit&eacute;, &eacute;tat et disponibilit&eacute;.</li><li>Conditions de transport ou stockage.</li><li>Contraintes de s&eacute;curit&eacute; ou conformit&eacute;.</li></ul></article><article><h3>Collectivit&eacute;</h3><ul><li>P&eacute;rim&egrave;tre territorial.</li><li>Objectifs de la demande.</li><li>Typologies de biens cibl&eacute;s.</li><li>Donn&eacute;es mobilisables dans un cadre autoris&eacute;.</li><li>Interlocuteur r&eacute;f&eacute;rent.</li></ul></article><article><h3>Projet ou association</h3><ul><li>Pr&eacute;sentation du projet.</li><li>Besoin immobilier ou mat&eacute;riel.</li><li>Public concern&eacute;.</li><li>Partenaires d&eacute;j&agrave; identifi&eacute;s.</li><li>Calendrier souhait&eacute;.</li></ul></article></div></section><section class="agency-section soft"><div class="agency-shell narrow"><p class="agency-kicker">Important</p><h2>Une demande ne vaut pas acceptation automatique.</h2><p>TVF peut demander des compl&eacute;ments, orienter vers un autre organisme ou classer une demande sans suite lorsque le cadre, les moyens ou les informations disponibles ne permettent pas d'intervenir.</p></div><section class="agency-section"><div class="agency-shell info-grid"><article><p class="agency-kicker">Principe de minimisation</p><h2>Ne transmettre que ce qui est utile.</h2><p>TVF ne demande pas de documents sensibles sans raison. Les pieces justificatives sont sollicitees progressivement, selon le niveau d'analyse du dossier et la qualite du demandeur.</p><p>Une premiere demande peut souvent etre etudiee avec une description claire, une localisation, des coordonnees et quelques informations de contexte.</p></article><article><p class="agency-kicker">Apres reception</p><h2>Les pieces sont rattachees au dossier.</h2><p>Lorsque la demande devient un dossier suivi, les documents utiles sont rattaches dans les outils internes de TVF. Les pieces inutiles, trop sensibles ou non pertinentes peuvent etre refusees ou faire l'objet d'une demande de clarification.</p></article></div></section></section>`; }
function tvfOsPublicPage(){ return `<section class="info-hero tvf-os-public-hero"><div class="agency-shell info-hero-grid"><div><p class="agency-kicker">TVF OS</p><h1>Comprendre comment une demande est suivie.</h1><p>TVF OS est l'outil interne qui permet de relier une demande, un contact, un dossier, des documents, des actions et des reponses. Il aide l'Agence a travailler de maniere suivie et tracable.</p><div class="agency-actions"><a class="agency-btn" href="admin-login" rel="nofollow">Acces TVF OS</a><a class="agency-btn agency-btn-alt" href="contact">Deposer une demande</a></div></div><div class="tvf-os-mockup" aria-hidden="true"><div class="mockup-top"><span>TVF OS</span><b>Demandes</b><b>Dossiers</b><b>Documents</b></div><div class="mockup-body"><aside><i></i><i></i><i></i><i></i></aside><main><div></div><div></div><div></div><div></div></main><section><strong>TVF-2026-001</strong><span>Qualification</span><span>Dossier en instruction</span></section></div></div></div></section><section class="agency-section"><div class="agency-shell section-title"><p class="agency-kicker">Parcours</p><h2>De la demande au dossier.</h2></div><ol class="actions-steps"><li><strong>Demande recue</strong><span>Le formulaire, l'e-mail ou TVF Mobile transmettent les premieres informations.</span></li><li><strong>Contact cree</strong><span>La personne ou structure est rattachee a une fiche contact.</span></li><li><strong>Qualification</strong><span>TVF identifie le profil, le motif, la categorie et le niveau de priorite.</span></li><li><strong>Dossier ouvert</strong><span>Si un suivi est necessaire, un dossier d'instruction est cree.</span></li><li><strong>Documents</strong><span>Les pieces utiles sont rattachees au dossier.</span></li><li><strong>Instruction</strong><span>Les etapes, statuts, echanges et orientations sont suivis.</span></li><li><strong>Cloture ou suite</strong><span>Le dossier est finalise, oriente, conventionne ou classe selon la situation.</span></li></ol></section><section class="agency-section soft"><div class="agency-shell info-grid"><article><p class="agency-kicker">Acces</p><h2>Un outil reserve.</h2><p>TVF OS n'est pas un espace public ouvert. Les acces sont reserves aux personnes autorisees selon leur role et leur besoin d'en connaitre.</p></article><article><p class="agency-kicker">Confidentialite</p><h2>Les donnees ne sont pas publiees.</h2><p>Les informations personnelles, adresses precises, documents et echanges restent destines au traitement interne ou aux partenaires habilites.</p></article></div></section><section class="agency-section"><div class="agency-shell info-grid"><article><p class="agency-kicker">Ce que le demandeur doit comprendre</p><h2>TVF OS ne remplace pas l'echange humain.</h2><p>L'outil sert a organiser les informations, conserver l'historique et eviter la perte de suivi. Les decisions importantes restent prises apres analyse du dossier, echange avec les personnes concernees et verification du cadre applicable.</p></article><article><p class="agency-kicker">Fonctions suivies</p><h2>Un cycle complet de dossier.</h2><ul><li>Demandes entrantes.</li><li>Contacts et fiches client.</li><li>Dossiers d'instruction.</li><li>Documents rattaches.</li><li>Courriers et reponses.</li><li>Cartographie et observatoire.</li><li>Indicateurs et rapports.</li></ul></article></div></section>`; }
function imageForSecondary(file){ const map={ 'agir-avec-nous.html': photos.solidarite, 'benevoles-citoyens.html': photos.solidarite, 'documents.html': photos.ressources, 'financeurs-mecenes.html': photos.ville, 'gouvernance.html': photos.ville, 'nos-poles.html': photos.habitat, 'notre-methode.html': photos.friches, 'transparence.html': photos.ville, 'kit-media.html': photos.hero }; return map[file] || photos.hero; }
function secondaryPage(file, title, desc){
  const data = {
    'agir-avec-nous.html': {k:'Agir avec TVF', h:'Contribuer a une action territoriale utile', p:'Cette entree oriente les proprietaires, collectivites, entreprises, associations et habitants vers les parcours adaptes de l\'Agence.', a:[['Je suis proprietaire','proprietaires'],['Je represente une collectivite','collectivites'],['Je represente une entreprise','entreprises'],['Je souhaite contacter TVF','contact']]},
    'benevoles-citoyens.html': {k:'Citoyens', h:'Signaler, proposer, participer', p:'Les habitants et benevoles peuvent contribuer en signalant une situation, en presentant un besoin local ou en rejoignant une action encadree lorsque le cadre de securite est defini.', a:[['Signaler une situation','contact'],['Comprendre nos actions','nos-actions'],['Contacter l\'Agence','contact']]},
    'kit-media.html': {k:'Kit media', h:'Informations publiques de presentation', p:'Cette page regroupe les informations publiques utiles pour presenter TVF : identite, coordonnees, statut associatif, logo officiel et contacts.', a:[['L\'Agence','qui-sommes-nous'],['Mentions legales','mentions-legales'],['Contact presse','contact']]},
    'nos-poles.html': {k:'Poles TVF', h:'Les poles sont desormais presentes dans Nos actions', p:'Habitat, commerce, friches, materiautheque, solidarite et insertion sont regroupes dans une page operationnelle unique afin de faciliter la comprehension.', a:[['Voir nos actions','nos-actions'],['Proposer un bien','proprietaires'],['Contact','contact']]},
    'notre-methode.html': {k:'Methode', h:'Une methode integree au parcours de l\'Agence', p:'La methode TVF est expliquee dans les pages L\'Agence, Proprietaires, Collectivites, Nos actions et Observatoire pour rester liee a chaque usage.', a:[['L\'Agence','qui-sommes-nous'],['Observatoire','observatoire'],['Contact','contact']]},
    'transparence.html': {k:'Transparence', h:'Une information claire, sans resultats inventes', p:'TVF distingue les objectifs, les travaux en structuration et les resultats verifies. Les chiffres et partenariats ne sont publies qu\'apres consolidation.', a:[['Impact','impact'],['Observatoire','observatoire'],['Mentions legales','mentions-legales']]},
    'financeurs-mecenes.html': {k:'Financeurs', h:'Soutenir une demarche territoriale encadree', p:'TVF peut echanger avec les financeurs, fondations et mecenes autour de projets documentes, conventionnes et suivis dans le respect du cadre applicable.', a:[['Decouvrir les actions','nos-actions'],['Proposer un partenariat','entreprises'],['Nous contacter','contact']]},
    'gouvernance.html': {k:'Organisation', h:'Un cadre associatif au service de l\'action', p:'Territoires Vivants France est une association loi 1901 qui organise ses interventions a travers une logique d\'agence territoriale, avec des parcours, des dossiers et des responsabilites identifiables.', a:[['L\'Agence','qui-sommes-nous'],['Mentions legales','mentions-legales'],['Contact','contact']]}
  };
  const d = data[file] || {k:title, h:title, p:desc, a:[['L\'Agence','qui-sommes-nous'],['Nos actions','nos-actions'],['Contact','contact']]};
  const links = d.a.map(x => '<a class="agency-btn agency-btn-alt" href="' + x[1] + '">' + x[0] + '</a>').join('');
  return `<section class="secondary-hero secondary-hero-premium"><div class="agency-shell secondary-hero-grid"><div><p class="agency-kicker">${d.k}</p><h1>${d.h}</h1><p>${d.p}</p><div class="agency-actions">${links}</div></div><figure><img src="${imageForSecondary(file)}" alt="Territoire vivant et centre-ville francais"></figure></div></section><section class="agency-section"><div class="agency-shell orientation-grid"><article><p class="agency-kicker">Orientation</p><h2>Une page recentree dans la nouvelle architecture</h2><p>Cette rubrique reste accessible afin de conserver une navigation claire, mais l'information principale est maintenant organisee par parcours : proprietaires, collectivites, entreprises, actions, observatoire et contact.</p></article><article><p class="agency-kicker">Fonctionnement</p><h2>Un acces simple au bon interlocuteur</h2><p>Si votre demande concerne un bien, un territoire, une contribution, un projet ou une question generale, le formulaire de contact permet d'orienter le sujet vers le bon parcours.</p><a class="agency-btn" href="contact">Presenter ma demande</a></article></div></section>`; }
function faqPage(){ return `<section class="secondary-hero"><div class="agency-shell secondary-hero-grid"><div><p class="agency-kicker">FAQ</p><h1>Questions fréquentes</h1><p>Des réponses simples pour comprendre comment présenter un bien, signaler une situation, proposer une ressource ou entrer en contact avec l’Agence.</p><div class="agency-actions"><a class="agency-btn" href="contact">Contacter TVF</a><a class="agency-btn agency-btn-alt" href="nos-actions">Voir nos actions</a></div></div><figure><img src="${photos.ville}" alt="Centre-ville et territoire"></figure></div></section><section class="owner-faq"><div class="agency-shell owner-faq-grid"><div><p class="agency-kicker">Réponses utiles</p><h2>Avant de déposer une demande</h2></div><div class="owner-accordion"><details><summary>TVF est-elle une agence immobilière classique ?</summary><p>TVF agit comme une Agence Territoriale de Revitalisation Immobilière portée par une association loi 1901. Elle accompagne l’étude, l’orientation et la remise en usage de biens vacants, sans se substituer aux professionnels réglementés lorsque leur intervention est nécessaire.</p></details><details><summary>Qui peut présenter un bien ?</summary><p>Un propriétaire, un représentant habilité, une collectivité ou un acteur disposant d’informations utiles peut transmettre une demande. La suite dépend des droits du propriétaire, du cadre juridique et des informations disponibles.</p></details><details><summary>Un signalement prouve-t-il qu’un bien est abandonné ?</summary><p>Non. Un signalement attire l’attention de TVF sur une situation. Il ne constitue pas une preuve juridique de vacance, d’abandon ou d’absence de propriétaire.</p></details><details><summary>TVF réalise-t-elle les travaux ?</summary><p>TVF peut orienter, organiser et mobiliser des partenaires. Les travaux nécessitant qualification, assurance ou autorisation sont réalisés par les professionnels compétents.</p></details><details><summary>Les aides sont-elles garanties ?</summary><p>Non. Les aides dépendent des critères d’éligibilité, du bien, du projet et des organismes compétents. TVF peut informer et orienter, sans promettre une attribution automatique.</p></details><details><summary>Comment ma demande est-elle suivie ?</summary><p>Elle est reçue, qualifiée, orientée puis, si nécessaire, transformée en dossier dans les outils internes de TVF.</p></details></div></div></section>`; }
function legalNoticePage(){ return `<section class="secondary-hero legal-hero"><div class="agency-shell"><p class="agency-kicker">Mentions légales</p><h1>Informations légales de Territoires Vivants France</h1><p>Cette page présente les informations administratives et éditoriales du site.</p></div></section><section class="agency-section"><div class="agency-shell legal-grid"><article><h2>Éditeur du site</h2><p><strong>Territoires Vivants France</strong><br>Association loi 1901 déclarée<br>RNA : ${contact.rna}<br>SIREN : ${contact.siren}<br>SIRET : ${contact.siret}<br>Siège : ${contact.address}</p><p>E-mail : <a href="mailto:${contact.email}">${contact.email}</a><br>Téléphone : <a href="tel:${contact.phoneHref}">${contact.phone}</a></p></article><article><h2>Direction de la publication</h2><p>Directeur de la publication : Edryan Rangoly, président fondateur.</p><h2>Objet du site</h2><p>Le site présente les actions de Territoires Vivants France, ses parcours de contact, ses informations publiques et ses outils de suivi.</p></article><article><h2>Hébergement</h2><p>Le site est hébergé via Vercel. Les informations techniques exactes pourront être complétées selon les paramètres définitifs du compte de déploiement.</p><h2>Responsabilité</h2><p>TVF s’efforce de publier des informations exactes et actualisées. Les informations présentées ne remplacent pas un conseil juridique, technique, fiscal ou réglementaire adapté à une situation particulière.</p></article></div></section>`; }
function privacyPage(){ return `<section class="secondary-hero legal-hero"><div class="agency-shell"><p class="agency-kicker">Données personnelles</p><h1>Politique de confidentialité</h1><p>TVF limite la collecte aux informations nécessaires au traitement des demandes et au suivi des dossiers.</p></div></section><section class="agency-section"><div class="agency-shell legal-grid"><article><h2>Données collectées</h2><p>Les formulaires peuvent recueillir l’identité, les coordonnées, le profil, la commune, la description de la demande, les informations sur un bien ou un projet et les documents utiles transmis volontairement.</p></article><article><h2>Finalités</h2><p>Les données servent à répondre à la demande, orienter le sujet vers le bon parcours, conserver un historique minimal, préparer un éventuel dossier et assurer le suivi interne.</p></article><article><h2>Accès et droits</h2><p>Les informations ne sont pas destinées à être publiées. Pour exercer vos droits d’accès, rectification, opposition ou suppression lorsque le cadre le permet, écrivez à <a href="mailto:${contact.email}">${contact.email}</a>.</p></article><article><h2>Conservation</h2><p>Les données sont conservées pendant une durée proportionnée à la nature de la demande, aux obligations applicables et aux besoins de suivi de TVF.</p></article></div></section>`; }
function mobilePrivacyPage(){ return `<section class="secondary-hero legal-hero"><div class="agency-shell"><p class="agency-kicker">TVF Mobile</p><h1>Confidentialité TVF Mobile</h1><p>TVF Mobile permet de transmettre des informations utiles au traitement d’un signalement ou d’une demande.</p></div></section><section class="agency-section"><div class="agency-shell legal-grid"><article><h2>Photos et localisation</h2><p>Les photos, descriptions et localisations transmises servent à qualifier la situation signalée. L’utilisateur ne doit pas entrer dans une propriété privée sans autorisation.</p></article><article><h2>Traitement</h2><p>Les informations peuvent être reliées à une demande, un contact ou un dossier dans TVF OS lorsque cela est nécessaire au suivi.</p></article><article><h2>Droits des personnes</h2><p>Pour exercer vos droits ou signaler une erreur, écrivez à <a href="mailto:${contact.email}">${contact.email}</a>.</p></article></div></section>`; }
function pageContent(file,title,desc){
  if(file === 'index.html') return home();
  if(file === 'qui-sommes-nous.html') return agencyAbout();
  if(file === 'proprietaires.html') return ownersPage();
  if(file === 'collectivites.html') return collectivitiesPage();
  if(file === 'entreprises.html') return enterprisesPage();
  if(file === 'nos-actions.html') return actionsPage();
  if(file === 'observatoire.html') return observatoryPage();
  if(file === 'contact.html') return contactPage();
  if(file === 'tvf-os.html') return tvfOsPublicPage();
  if(file === 'saint-etienne.html') return saintEtiennePage();
  if(file === 'partenaires.html') return partnersPage();
  if(file === 'impact.html') return impactPage();
  if(file === 'ressources.html') return resourcesPage();
  if(file === 'documents.html') return piecesPage();
  if(file === 'faq.html') return faqPage();
  if(file === 'mentions-legales.html') return legalNoticePage();
  if(file === 'politique-confidentialite.html') return privacyPage();
  if(file === 'confidentialite-mobile.html') return mobilePrivacyPage();
  return secondaryPage(file,title,desc);
}
function layout(page){ const file=page[0], label=page[1], title=page[2], desc=page[3]; const canonical=pageUrl(file); return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + ' | ' + site.name + '</title><meta name="description" content="' + esc(desc) + '"><meta name="robots" content="index, follow"><meta name="theme-color" content="#07351f"><link rel="canonical" href="' + canonical + '"><meta property="og:locale" content="fr_FR"><meta property="og:site_name" content="' + site.name + '"><meta property="og:title" content="' + esc(title) + ' | ' + site.name + '"><meta property="og:description" content="' + esc(desc) + '"><meta property="og:type" content="website"><meta property="og:url" content="' + canonical + '"><meta property="og:image" content="' + site.url + '/assets/logo-territoires-vivants-france-web.png"><link rel="icon" href="assets/favicon-32.png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><link rel="manifest" href="site.webmanifest"><link rel="stylesheet" href="styles.css"></head><body class="agency-site"><a class="skip-link" href="#contenu">Aller au contenu</a>' + header(file) + '<main id="contenu">' + pageContent(file,title,desc) + '</main>' + footer() + '<script src="main.js" defer></script></body></html>'; }
for (const page of pages) fs.writeFileSync(page[0], layout(page), "utf8");
for (const file of legacy) fs.writeFileSync(file, layout([file,"Archive","Page retiree de la navigation","Cette page publique a ete retiree pendant la reconstruction du portail officiel."]), "utf8");
const urls = pages.map(function(page){ return '  <url><loc>' + pageUrl(page[0]) + '</loc></url>'; }).join("\n");
fs.writeFileSync("sitemap.xml", '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + urls + '\n</urlset>\n', "utf8");
fs.writeFileSync("robots.txt", 'User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /api\nDisallow: /documents\nSitemap: ' + site.url + '/sitemap.xml\n', "utf8");
console.log("Generated agency public site: " + (pages.length + legacy.length) + " pages.");